-- Add source-checked Tech Core spells without replacing existing records or saved characters.
do $import_tech_general$
declare
  v_spec constant jsonb := $tech_core_general${"schema":"wg-tech-core-general-spells-private-draft-v1","sources":[{"id":1,"name":"Player Core","user_id":null,"is_published":true,"deprecated":null,"url":"https://paizo.com/products/btq02eoj?Pathfinder-Player-Core","group":"pathfinder-core","required_content_sources":[],"require_key":false},{"id":3,"name":"Common Core","user_id":null,"is_published":true,"deprecated":false,"url":null,"group":"common-core","required_content_sources":[],"require_key":false},{"id":7,"name":"GM Core","user_id":null,"is_published":true,"deprecated":null,"url":"https://paizo.com/products/btq02ej3?Pathfinder-GM-Core","group":"pathfinder-core","required_content_sources":[1],"require_key":false},{"id":15,"name":"Rage of Elements","user_id":null,"is_published":true,"deprecated":null,"url":"https://paizo.com/products/btq02eju?Pathfinder-Rage-of-Elements","group":"pathfinder-core","required_content_sources":[1],"require_key":false},{"id":579,"name":"Starfinder Player Core","user_id":null,"is_published":true,"deprecated":null,"url":"https://paizo.com/products/btq09jzb?Starfinder-Player-Core","group":"starfinder-core","required_content_sources":[],"require_key":false},{"id":793,"name":"Starfinder GM Core","user_id":null,"is_published":true,"deprecated":null,"url":"https://store.paizo.com/starfinder-2e-gm-core/","group":"starfinder-core","required_content_sources":[579],"require_key":false},{"id":900,"name":"Tech Core","user_id":null,"is_published":true,"deprecated":null,"url":"https://store.paizo.com/starfinder-tech-core/","group":"starfinder-core","required_content_sources":null,"require_key":false}],"references":[{"table":"item","row":{"id":15059,"created_at":"2024-07-07T17:07:07.826836+00:00","name":"Cold Iron","bulk":null,"level":2,"rarity":"COMMON","description":"Weapons made from [cold](link_trait_1519) iron are deadly to demons and [fey](link_trait_2021) alike. Cold iron looks like normal iron but is mined from particularly pure sources and shaped with little or no heat. This process is extremely difficult, especially for high-grade cold iron items.\n\n#### Cold Iron Items\n\n| Cold Iron Items | Hardness | HP | BT |\n\n|---|---|---|---|\n\n| Thin Items: Low-grade | 5 | 20 | 10 |\n\n| Thin Items: Standard-grade | 7 | 28 | 14 |\n\n| Thin Items: High-grade | 10 | 40 | 20 |\n\n| Items: Low-grade | 9 | 36 | 18 |\n\n| Items: Standard-grade | 11 | 44 | 22 |\n\n| Items: High-grade | 14 | 56 | 28 |\n\n| Structures: Low-grade | 18 | 72 | 136 |\n\n| Structures: Standard-grade | 22 | 88 | 44 |\n\n| Structures: High-grade | 28 | 112 | 56 |","group":"MATERIAL","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"","dice":1,"extra":"","damageType":""},"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=2916","book":"GM Core","page":"253"},"charges":{},"foundry":{},"category":"","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":true},"operations":[],"content_source_id":7,"version":"1.0","uuid":7759550264640819,"price":{},"traits":[1533],"availability":null}},{"table":"item","row":{"id":15062,"created_at":"2024-07-07T17:24:52.597853+00:00","name":"Silver","bulk":null,"level":2,"rarity":"COMMON","description":"Silver weapons are a bane to creatures ranging from [devils](link_trait_2436) to [werewolves](link_trait_2471). Silver items are less durable than steel items, and low-grade silver items are usually merely silver-plated.\n\n#### **Silver Items**\n\n| Silver Items | Hardness | HP | BT |\n\n|---|---|---|---|\n\n| Thin Items: Low-grade | 3 | 12 | 6 |\n\n| Thin Items: Standard-grade | 5 | 20 | 10 |\n\n| Thin Items: High-grade | 8 | 32 | 16 |\n\n| Items: Low-grade | 5 | 20 | 10 |\n\n| Items: Standard-grade | 7 | 28 | 14 |\n\n| Items: High-grade | 10 | 40 | 20 |\n\n| Structures: Low-grade | 10 | 40 | 20 |\n\n| Structures: Standard-grade | 14 | 56 | 28 |\n\n| Structures: High-grade | 20 | 80 | 40 |","group":"MATERIAL","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=2920","book":"GM Core","page":"254"},"charges":{},"foundry":{},"category":"","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":true},"operations":[],"content_source_id":7,"version":"1.0","uuid":5637968875392,"price":{},"traits":[1533],"availability":null}},{"table":"ability_block","row":{"id":19611,"created_at":"2023-12-13T20:30:43.277321+00:00","operations":[],"name":"Cast a Spell","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"Spells can vary in how many actions they take, as shown in the spell’s stat block. You cast cantrips, spells from spell slots, and focus spells using the same process, but must expend the spell when casting a spell from a spell slot and must spend 1 Focus Point to cast a focus spell. Some rules will refer to the Cast a Spell activity, such as “if the next action you use is to Cast a Spell.” Any spell qualifies as a Cast a Spell activity, and any characteristics of the spell use those of the specific spell you’re casting.\n\n### **Costs and Loci**\n\nSome spells require you to pay a cost or provide a locus. If the spell lists a cost, you must have the listed money, valuable materials, or other resources to cast the spell (such as gems or magical reagents), and they're expended during the casting.\n\nA locus is an object that funnels or directs the magical energy of the spell but is not consumed in its casting. As part of Casting the Spell, you retrieve the locus (if necessary, and if you have a free hand), and you can put it away again if you so choose. Loci tend to be expensive, and you need to acquire them in advance to cast the spell, but they aren't expended like costs are. Unless noted otherwise, a locus has negligible Bulk.\n\n### **Long Casting Times**\n\nSome spells take minutes or hours to cast. You can’t use other actions or reactions while casting such a spell, though at the GM’s discretion, you might be able to speak a few sentences. As with other activities that take a long time, these spells have the exploration trait, and you can’t cast them in an encounter. If combat breaks out while you’re casting one, your spell is disrupted.\n\n### **Disrupted and Lost Spells**\n\nSome abilities and spells can disrupt a spell, causing it to have no effect and be lost. When you lose a spell, you’ve already expended the spell slot and spent the spell’s costs and actions. If a spell is disrupted during a [Sustain](link_action_19858) action, the spell immediately ends.","special":null,"type":"action","meta_data":{"foundry":{"rules":[]}},"traits":[],"content_source_id":3,"version":"1.0","uuid":3222895456836016,"availability":null}},{"table":"item","row":{"id":15064,"created_at":"2024-07-07T17:28:27.505859+00:00","name":"Adamantine","bulk":null,"level":8,"rarity":"UNCOMMON","description":"Mined from rocks that fell from the heavens, adamantine is one of the hardest metals known. It has a shiny, black appearance, and it is prized for its amazing resiliency and ability to hold an incredibly sharp edge.\n\n#### Adamantine Items\n\n| Adamantine Items | Hardness | HP | BT |\n\n|---|---|---|---|\n\n| Thin Items: Standard-grade | 10 | 40 | 20 |\n\n| Thin Items: High-grade | 13 | 52 | 26 |\n\n| Items: Standard-grade | 14 | 56 | 28 |\n\n| Items: High-grade | 17 | 68 | 34 |\n\n| Structures: Standard-grade | 28 | 112 | 56 |\n\n| Structures: High-grade | 34 | 136 | 68 |","group":"MATERIAL","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"","dice":1,"extra":"","damageType":""},"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=2915","book":"GM Core","page":"253"},"charges":{},"foundry":{},"category":"","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":true},"operations":[],"content_source_id":7,"version":"1.0","uuid":4177135793148293,"price":{},"traits":[1533],"availability":null}},{"table":"trait","row":{"id":1432,"created_at":"2023-12-02T22:32:54.192399+00:00","name":"Concentrate","description":"An action with this trait requires a degree of mental concentration and discipline to perform.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=561","book":"Player Core","page":"454"}},"content_source_id":3,"uuid":3011511166869167}},{"table":"trait","row":{"id":1433,"created_at":"2023-12-02T22:32:55.850689+00:00","name":"Manipulate","description":"You must physically manipulate an item or make gestures to use an action with this trait. Creatures without a suitable appendage can’t perform actions with this trait. Manipulate actions often trigger reactions.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=645","book":"Player Core","page":"458"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false},"content_source_id":3,"uuid":2971108648217689}},{"table":"trait","row":{"id":2132,"created_at":"2023-12-18T04:13:02.75537+00:00","name":"Metal","description":"Effects with the metal trait conjure or manipulate metal. Those that manipulate metal have no effect in an area without metal. Creatures with this trait consist primarily of metal or have a connection to magical metal.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=505","book":"Player Core","page":"458"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":1655077625479333}},{"table":"trait","row":{"id":4506,"created_at":"2025-06-27T23:38:56.418203+00:00","name":"Tech","description":"Equipment with the tech trait rely on electricity and may gain the glitching condition. Some creatures and hazards also have the tech trait, such as artificial intelligence, robots, and turrets.\n\nArmor with the tech trait incorporate electronics, computer systems, integrated power sources, and a [comm unit](link_item_16072).\n\nShields with the tech trait incorporate electronics, computer systems, and integrated power sources.\n\nWeapons with the tech trait incorporate electronics, computer systems, and power sources. Usually the weapons rely on integrated power sources (such as melee weapons that don't have the [powered](link_trait_4670) trait), while others drain batteries with each attack.\n\nCybernetic augmentations are technological, not magical, though they aren't subject to any effect or attack that targets technology unless it specifies that it affects cybernetics.","meta_data":{"source":{"url":"https://2e.aonsrd.com/traits/179-tech","book":"Starfinder Player Core","page":"455"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":579,"uuid":8353387345040544}},{"table":"trait","row":{"id":3070,"created_at":"2024-04-27T07:57:22.479635+00:00","name":"Summon","description":"Spells with the summon trait can conjure creatures, typically ones with a particular trait. Such creatures can be found in _Monster Core_ and similar books. Unless noted otherwise, the creature must be common, it gains the [summoned](link_trait_2134) trait, and it must appear in an unoccupied space in range large enough to contain it. The highest level of creature the spell can summon depends on the rank of the spell, as listed below. The spell can still summon a creature of a lower level if you so choose. These rules apply only to spells that have the summon trait; other spells that call or conjure items or beings but that don't have the trait, like [_summon instrument_](link_spell_4875), work as explained in the spell.\n\n* * *\n\n| Spell Rank | Maximum Creature Level |\n\n|:--------------:|:---------------------------------:|\n\n| 1st | -1 |\n\n| 2nd | 1 |\n\n| 3rd | 2 |\n\n| 4th | 3 |\n\n| 5th | 5 |\n\n| 6th | 7 |\n\n| 7th | 9 |\n\n| 8th | 11 |\n\n| 9th | 13 |\n\n| 10th | 15 |","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=520","book":"Player Core","page":"360"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":1097291325651328}},{"table":"trait","row":{"id":1576,"created_at":"2023-12-03T18:53:26.920346+00:00","name":"Electricity","description":"Effects with this trait deal electricity damage. A creature with this trait has a [magical](link_trait_1504) connection to electricity.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=586","book":"Player Core","page":"455"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":8962290357294145}},{"table":"ability_block","row":{"id":19858,"created_at":"2023-12-14T00:27:10.903097+00:00","operations":null,"name":"Sustain","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"Choose one of your effects that has a sustained duration or lists a special benefit when you Sustain it. Most such effects come from spells or magic item activations. If the effect has a sustained duration, its duration extends until the end of your next turn. (Sustaining more than once in the same turn doesn't extend the duration to subsequent turns.) If an ability can be sustained but doesn't list how long, it can be sustained up to 10 minutes.\n\nAn effect might list an additional benefit that occurs if you Sustain it, and this can even appear on effects that don't have a sustained duration. If the effect has both a special benefit and a sustained duration, your Sustain action extends the duration as well as having the special benefit.\n\nIf your Sustain action is disrupted, the ability ends.","special":null,"type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2317","book":"Player Core","page":"419"},"foundry":{"rules":[]}},"traits":[1432],"content_source_id":3,"version":"1.0","uuid":7845751305633010,"availability":null}},{"table":"trait","row":{"id":1517,"created_at":"2023-12-02T23:26:03.801207+00:00","name":"Light","description":"Light effects overcome non-magical darkness in the area, and can [counteract](link_action_27519) [magical](link_trait_1504) [darkness](link_trait_1900). You must usually target darkness magic with your light magic directly to counteract the darkness, but some light spells automatically attempt to counteract darkness.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=640","book":"Player Core","page":"458"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":7362437638210779}},{"table":"trait","row":{"id":1479,"created_at":"2023-12-02T22:38:20.607425+00:00","name":"Visual","description":"A visual effect can affect only creatures that can see it. This applies only to visible parts of the effect, as determined by the GM.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=727","book":"Player Core","page":"463"},"important":true},"content_source_id":3,"uuid":4675954693812974}},{"table":"trait","row":{"id":1569,"created_at":"2023-12-03T18:52:57.920674+00:00","name":"Agile","description":"The multiple attack penalty you take with this weapon on the second attack on your turn is -4 instead of -5, and -8 instead of -10 on the third and subsequent attacks in the turn.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=526","book":"Player Core","page":"282"},"important":true},"content_source_id":3,"uuid":8144183238496458}},{"table":"trait","row":{"id":1619,"created_at":"2023-12-03T19:01:49.465166+00:00","name":"Backswing","description":"You can use the momentum from a missed attack with this weapon to lead into your next attack. After missing with this weapon on your turn, you gain a +1 circumstance bonus to your next attack with this weapon before the end of your turn.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=545","book":"Player Core","page":"282"},"important":true},"content_source_id":3,"uuid":3278692078311684}},{"table":"trait","row":{"id":1598,"created_at":"2023-12-03T18:58:24.704021+00:00","name":"Forceful","description":"This weapon becomes more dangerous as you build momentum. When you attack with it more than once on your turn, the second attack gains a circumstance bonus to damage equal to the number of weapon damage dice, and each subsequent attack gains a circumstance bonus to damage equal to double the number of weapon damage dice.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=611","book":"Player Core","page":"282"},"important":true},"content_source_id":3,"uuid":4896476829341793}},{"table":"trait","row":{"id":1573,"created_at":"2023-12-03T18:53:08.705751+00:00","name":"Reach","description":"This weapon is long and can be used to attack creatures up to 10 feet away instead of only adjacent creatures. For creatures that already have reach with the limb or limbs that wield the weapon, the weapon increases their reach by 5 feet.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=684","book":"Player Core","page":"283"}},"content_source_id":3,"uuid":175486816832894}},{"table":"trait","row":{"id":1562,"created_at":"2023-12-03T18:52:10.609863+00:00","name":"Sweep","description":"This weapon makes wide sweeping or spinning attacks, making it easier to attack multiple enemies. When you attack with this weapon, you gain a +1 circumstance bonus to your attack roll if you already attempted to attack a different target this turn using this weapon.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=708","book":"Player Core","page":"283"},"important":true},"content_source_id":3,"uuid":8190519161588551}},{"table":"trait","row":{"id":1560,"created_at":"2023-12-03T18:51:58.121654+00:00","name":"Force","description":"Effects with this trait deal force damage or create objects made of pure magical force.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=610","book":"Player Core","page":"456"}},"content_source_id":3,"uuid":1798173688310192}},{"table":"trait","row":{"id":1484,"created_at":"2023-12-02T22:39:46.549843+00:00","name":"Sonic","description":"An effect with the sonic trait functions only if it makes sound, meaning it has no effect in an area of silence or in a vacuum. This is different from an [auditory](link_trait_1469) spell, which is effective only if the target can hear it. A sonic effect might deal sonic damage.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=697","book":"Player Core","page":"461"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":1815257066620819}},{"table":"trait","row":{"id":1469,"created_at":"2023-12-02T22:36:54.899421+00:00","name":"Auditory","description":"Auditory actions and effects rely on sound. An action with the auditory trait can be successfully performed only if the creature using the action can speak or otherwise produce the required sounds. A spell or effect with the auditory trait has its effect only if the target can hear it. This applies only to sound-based parts of the effect, as determined by the GM. This is different from a [sonic](link_trait_1484) effect, which still affects targets who can’t hear it (such as deaf targets) as long as the effect itself makes sound.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=541","book":"Player Core","page":"453"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":6475190443898764}},{"table":"trait","row":{"id":1442,"created_at":"2023-12-02T22:33:28.554367+00:00","name":"Healing","description":"A healing effect restores a creature's body, typically by restoring Hit Points, but sometimes by removing [diseases](link_trait_1857) or other debilitating effects.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=623","book":"Player Core","page":"457"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3679520362407580}},{"table":"trait","row":{"id":1478,"created_at":"2023-12-02T22:38:09.080969+00:00","name":"Vitality","description":"Effects with this trait heal living creatures with energy from the Forge of Creation, deal vitality energy damage to [undead](link_trait_2425), or manipulate vitality energy.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=509","book":"Player Core","page":"463"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":1588449051813870}},{"table":"ability_block","row":{"id":21146,"created_at":"2024-04-07T01:56:13.979282+00:00","operations":[],"name":"Avoid Notice","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"You attempt a Stealth check to avoid notice while traveling at half speed. If you're Avoiding Notice at the start of an encounter, you usually roll a Stealth check instead of a Perception check both to determine your initiative and to see if the enemies notice you (based on their Perception DCs, as normal for [Sneak](link_action_19850), regardless of their initiative check results).","special":"","type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2622","book":"Player Core","page":"438"}},"traits":[1457],"content_source_id":3,"version":"1.0","uuid":3428789436847928,"availability":null}},{"table":"item","row":{"id":18663,"created_at":"2025-08-10T21:04:48.043298+00:00","name":"Comm Unit","bulk":"0.1","level":1,"rarity":"COMMON","description":"A personal comm unit is a pocket-sized device that combines a minor portable computer and a cellular communications device, allowing instantaneous wireless communication with other comm units in both audio- and textbased formats at planetary range. A personal comm unit also includes a calculator, a flashlight (emits bright light in a 5-foot radius around you and dim light in the next 5 feet), a browser that accesses any local infospheres, and several entertainment options (including games).\n\nPersonal comm units integrated into armor have some voice-activated capabilities; you can communicate with other comm units in audio-based formats and receive responses without needing a free hand, but typing a message, browsing the infosphere, or using an app requires the use of at least one hand.\n\nComm units that function at longer ranges aren’t as portable; they include built-in generators that provide the necessary amount of power and rely on active Drift beacons to communicate. Short-term use of these units can be purchased in most major settlements.","group":"GENERAL","hands":"1","size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"","dice":1,"extra":"","damageType":""},"source":{"url":"https://2e.aonsrd.com/treasure/7-comm-unit","book":"Starfinder Player Core","page":"241"},"charges":{},"foundry":{},"category":"","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":1897857600014837,"price":{"sp":7},"traits":[4506],"availability":null}},{"table":"ability_block","row":{"id":19733,"created_at":"2023-12-13T22:29:43.563844+00:00","operations":null,"name":"Interact","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You use your hand or hands to manipulate an object or the terrain. You can grab an unattended or stored object, draw a weapon, swap a held item for another, open a door, or achieve a similar effect. On rare occasions, you might have to attempt a skill check to determine if your Interact action was successful.","special":null,"type":"action","meta_data":{"foundry":{"rules":[]}},"traits":[1437,1433],"content_source_id":3,"version":"1.0","uuid":3402914292668269,"availability":null}},{"table":"trait","row":{"id":1542,"created_at":"2023-12-03T18:50:27.813878+00:00","name":"Fire","description":"Effects with the fire trait deal fire damage or either conjure or manipulate fire. Those that manipulate fire have no effect in an area without fire. Creatures with this trait consist primarily of fire or have a [magical](link_trait_1504) connection to that element. Planes with this trait are composed of flames that continually burn with no fuel source. Fire planes are extremely hostile to non-fire creatures.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=604","book":"Player Core","page":"456"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3316639745394270}},{"table":"trait","row":{"id":1528,"created_at":"2023-12-03T18:49:38.270608+00:00","name":"Acid","description":"Effects with this trait deal acid damage. Creatures with this trait have a [magical](link_trait_1504) connection to acid.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=524","book":"Player Core","page":"452"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3270346089098991}},{"table":"trait","row":{"id":1519,"created_at":"2023-12-02T23:27:36.874355+00:00","name":"Cold","description":"Effects with this trait deal cold damage. Creatures with this trait have a connection to [magical](link_trait_1504) cold.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=555","book":"Player Core","page":"454"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":196418167509}},{"table":"trait","row":{"id":1505,"created_at":"2023-12-02T23:18:17.183544+00:00","name":"Move","description":"An action with this trait involves moving from one space to another.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=658","book":"Player Core","page":"458"}},"content_source_id":3,"uuid":5829495615383177}},{"table":"ability_block","row":{"id":19855,"created_at":"2023-12-14T00:25:49.42181+00:00","operations":null,"name":"Stride","actions":"ONE-ACTION","level":1,"rarity":"COMMON","prerequisites":[],"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You move up to your Speed.","special":null,"type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2305","book":"Player Core","page":"418"},"foundry":{"rules":[]}},"traits":[1505],"content_source_id":3,"version":"1.0","uuid":3622379426522088,"availability":null}},{"table":"item","row":{"id":20388,"created_at":"2026-02-17T18:00:21.125986+00:00","name":"Hoverboard","bulk":"1","level":0,"rarity":"COMMON","description":"**Vehicle Type** Land Vehicle\n\n**Space** 4 feet long, 1 foot wide, 6 inches high\n\n**Crew** 1 pilot; Passengers\n\n**Piloting Check** Piloting (DC 14), Acrobatics (DC 15), or Athletics (DC 16)\n\n**AC** 11; **Fort** +5\n\n**Immunities** object immunities\n\n**Speed** fly 40 feet ([motorized](link_trait_5025))\n\n**Collision** 1d8 (DC 14)\n\n**Hover** A hoverboard maintains an altitude of 6 inches above other surfaces, such as the ground or water. If driven off a high surface, the hoverboard loses 20 feet of altitude per round, landing without harm to the hoverboard or its pilot.\n\n**Portable** The hoverboard can be carried as an item with 1 Bulk.","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":14,"source":{"url":"https://2e.aonsrd.com/equipment/vehicles/5-hoverboard","book":"Starfinder GM Core","page":"238"},"charges":{"max":0},"foundry":{},"category":"","hardness":3,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false,"broken_threshold":7},"operations":[],"content_source_id":793,"version":"1.0","uuid":1862367663212538,"price":{"sp":90},"traits":[4506],"availability":null}},{"table":"item","row":{"id":20396,"created_at":"2026-02-17T18:05:00.652318+00:00","name":"Forklift","bulk":null,"level":1,"rarity":"COMMON","description":"**Vehicle Type** Land Vehicle\n\n**Space** 10 feet long, 5 feet wide, 7 feet high\n\n**Crew** 1 pilot; Passengers\n\n**Piloting Check** Piloting (DC 15)\n\n**AC** 11; **Fort** +7\n\n**Immunities** object immunities\n\n**Speed** 20 feet ([motorized](link_trait_5025))\n\n**Collision** 2d6 (DC 15)\n\n**Heavy Load** A forklift carries its cargo on its front forks and can carry up to 1,000 Bulk.\n\n**Lift** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> The pilot raises the forklift's forks up to 15 feet in the air, or lowers the forklift's forks down to the ground.","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":18,"source":{"url":"https://2e.aonsrd.com/equipment/vehicles/6-forklift","book":"Starfinder GM Core","page":"238"},"charges":{},"foundry":{},"category":"","hardness":5,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false,"broken_threshold":9},"operations":[],"content_source_id":793,"version":"1.0","uuid":2878664266922509,"price":{"sp":100},"traits":[4506],"availability":null}},{"table":"item","row":{"id":22145,"created_at":"2026-03-04T19:54:22.561836+00:00","name":"Urban Cruiser","bulk":null,"level":4,"rarity":"COMMON","description":"**Vehicle Type** Land Vehicle\n\n**Space** 10 feet long, 10 feet wide, 4 feet high\n\n**Crew** 1 pilot; Passengers 3\n\n**Piloting Check** Piloting (DC 19)\n\n**AC** 16; **Fort** +11\n\n**Immunities** object immunities\n\n**Speed** 55 feet ([motorized](link_trait_5025))\n\n**Collision** 2d10 (DC 19)\n\n**Middle Seat** A Small creature can fit in the backseat of an urban cruiser that already has 3 passengers.","group":"GENERAL","hands":null,"size":"LARGE","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":60,"source":{"url":"https://2e.aonsrd.com/equipment/vehicles/8-urban-cruiser","book":"Starfinder GM Core","page":"239"},"charges":{},"foundry":{},"category":"","hardness":5,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false,"broken_threshold":30},"operations":[],"content_source_id":793,"version":"1.0","uuid":6672152171918348,"price":{"sp":3000},"traits":[4506],"availability":null}},{"table":"item","row":{"id":22137,"created_at":"2026-03-04T19:32:11.415116+00:00","name":"Torpedo Minisub","bulk":null,"level":3,"rarity":"COMMON","description":"**Vehicle Type** Sea Vehicle\n\n**Space** 10 feet long, 5 feet wide, 3 feet high\n\n**Crew** 1 pilot; Passengers 1\n\n**Piloting Check** Piloting (DC 17) or Nature (DC 19)\n\n**AC** 14; **Fort** +8\n\n**Immunities** object immunities\n\n**Speed** swim 40 feet ([motorized](link_trait_5025))\n\n**Collision** 2d10 (DC 18)\n\n**Submersible** The torpedo minisub can travel beneath the surface of the water, carrying an air reservoir suitable to sustain 2 Medium creatures for up to 24 hours. The torpedo minisub can safely reach depths of up to 1 mile. If broken, the torpedo minisub loses air from its reservoir, reducing the stored air by 10 minutes per round. A broken torpedo minisub has its maximum depth reduced by half (and rises to that depth when broken, if necessary).","group":"GENERAL","hands":null,"size":"LARGE","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":40,"source":{"url":"https://2e.aonsrd.com/equipment/vehicles/10-torpedo-minisub","book":"Starfinder GM Core","page":"239"},"charges":{},"foundry":{},"category":"","hardness":5,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false,"broken_threshold":20},"operations":[],"content_source_id":793,"version":"1.0","uuid":2276073797330708,"price":{"sp":1500},"traits":[4506],"availability":null}},{"table":"item","row":{"id":22133,"created_at":"2026-03-04T19:28:05.668867+00:00","name":"Skyboat","bulk":null,"level":3,"rarity":"COMMON","description":"**Vehicle Type** Air Vehicle\n\n**Space** 15 feet long, 10 feet wide, 3 feet high\n\n**Crew** 1 pilot, 1 crew; Passengers 4\n\n**Piloting Check** Piloting (DC 17) or Nature (DC 19)\n\n**AC** 16; **Fort** +10\n\n**Immunities** [electricity](link_trait_1576), object immunities\n\n**Speed** fly 40 feet ([magical](link_trait_1504)) or fly 60 feet ([wind](link_trait_5031))\n\n**Collision** 2d10 (DC 20)\n\n**Harness the Storm** <abbr cost=\"THREE-ACTIONS\" class=\"action-symbol\">3</abbr> ([electricity](link_trait_1576)) **Requirements** The skyboat is in a rainstorm; **Effect** The skyboat harnesses the storm's electrical energy through its magical sails, then expels this energy as a bolt of lightning that erupts from the front of the skyboat. The lightning deals 2d8 electricity damage to each creature in a 60-foot line (DC 18 basic Reflex save). Harness the Storm stops working if the skyboat is broken.","group":"GENERAL","hands":null,"size":"HUGE","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":80,"source":{"url":"https://2e.aonsrd.com/equipment/vehicles/2-skyboat","book":"Starfinder GM Core","page":"238"},"charges":{},"foundry":{},"category":"","hardness":10,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false,"broken_threshold":40},"operations":[],"content_source_id":793,"version":"1.0","uuid":293103892012061,"price":{"sp":1500},"traits":[1504,4506],"availability":null}},{"table":"item","row":{"id":22129,"created_at":"2026-03-04T19:15:03.720557+00:00","name":"Turboglider","bulk":null,"level":1,"rarity":"COMMON","description":"**Vehicle Type** Air Vehicle\n\n**Space** 4 feet long, 10 feet wide, 1 foot high\n\n**Crew** 1 pilot; Passengers 1 ([motorized](link_trait_5025) only)\n\n**Piloting Check** Piloting (DC 14) or Nature (DC 16)\n\n**AC** 12; **Fort** +6\n\n**Immunities** object immunities; **Weaknesses** fire 5\n\n**Speed** fly 60 feet ([motorized](link_trait_5025)) or fly 40 feet ([wind](link_trait_5031))\n\n**Collision** 1d8 (DC 15)\n\n**Cruising Drop** The only way to use the wind propulsion of a turboglider is to jump off a steep incline or if you're already in the air. An uncontrolled turboglider using wind propulsion falls 60 feet each round until the pilot successfully Takes Control. A turboglider must be controlled to switch propulsion. If the glider hits the ground before the pilot successfully [Takes Control](link_action_46740), the pilot and the glider each take falling damage.","group":"GENERAL","hands":null,"size":"LARGE","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":14,"source":{"url":"https://2e.aonsrd.com/equipment/vehicles/1-turboglider","book":"Starfinder GM Core","page":"238"},"charges":{},"foundry":{},"category":"","hardness":5,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false,"broken_threshold":7},"operations":[],"content_source_id":793,"version":"1.0","uuid":2431203344085259,"price":{"sp":100},"traits":[4506],"availability":null}},{"table":"item","row":{"id":22141,"created_at":"2026-03-04T19:37:21.87249+00:00","name":"Drop Pod","bulk":null,"level":4,"rarity":"COMMON","description":"**Vehicle Type** Space Vehicle\n\n**Space** 12 feet long, 12 feet wide, 15 feet high\n\n**Crew** 1 pilot; Passengers 5\n\n**Piloting Check** Piloting (DC 18), Computers (DC 20), or Survival (DC 20)\n\n**AC** 16; **Fort** +11\n\n**Immunities** object immunities; **Resistances** fire 10\n\n**Speed** controlled plummet ([motorized](link_trait_5025))\n\n**Collision** 2d10 (DC 19)\n\n**Controlled Plummet** This vehicle is programmed to deploy from another airborne vehicle or spaceship and fall toward the ground at a rate of 500 feet the first round and 1,500 feet each round thereafter, for a world with normal gravity. One round before impact, antigrav rotors, parachutes, and retrorockets slow the descent to 60 feet per round, allowing for a safe landing (even if uncontrolled).\n\n**Enclosed** The pilot and passengers of a drop pod are completely enclosed and don't have line of sight or line of effect with any creatures or objects outside the vehicle.\n\n**Space Vehicle** This vehicle protects its users from the dangers of space, including the benefits of [basic environmental protection](link_item_19567) and a [commercial filtered rebreather](link_item_19777).","group":"GENERAL","hands":null,"size":"HUGE","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"","runes":{"property":[]},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":70,"source":{"url":"https://2e.aonsrd.com/equipment/vehicles/11-drop-pod","book":"Starfinder GM Core","page":"239"},"charges":{},"foundry":{},"category":"","hardness":15,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false,"broken_threshold":35},"operations":[],"content_source_id":793,"version":"1.0","uuid":2396931803519037,"price":{"sp":2500},"traits":[4506],"availability":null}},{"table":"trait","row":{"id":5225,"created_at":"2026-10-08T04:30:41.323377+00:00","name":"Junk","description":"Spells with the junk trait use scrap, trash, and other debris found in any environment. While casting a junk spell requires no locus, it assumes the spellcaster always has access to discarded scraps or naturally occurring detritus. If the caster has absolutely nothing on their person or in their environment, they might be unable to cast a junk spell.","meta_data":{"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":900,"uuid":8693519255012780}},{"table":"trait","row":{"id":1846,"created_at":"2023-12-03T19:18:51.92214+00:00","name":"Unholy","description":"Effects with the unholy trait are tied to powerful magical forces of cruelty and sin. They often have stronger effects on holy creatures. Creatures with this trait are strongly devoted to unholy causes, and often have weakness to [holy](link_trait_1630). If a creature with weakness to unholy uses an unholy item or effect, it takes damage from its weakness.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=521","book":"Player Core","page":"462"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":6117148032754070}},{"table":"ability_block","row":{"id":19721,"created_at":"2023-12-13T22:24:37.866856+00:00","operations":null,"name":"Fly","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":"You have a fly Speed.","access":null,"description":"You move through the air up to your fly Speed. Moving upward (straight up or diagonally) uses the rules for moving through difficult terrain. You can move straight down 10 feet for every 5 feet of movement you spend. If you Fly to the ground, you don't take falling damage. You can use an action to Fly 0 feet to hover in place. If you're airborne at the end of your turn and didn't use a Fly action this round, you fall.","special":null,"type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2312","book":"Player Core","page":"419"},"foundry":{"rules":[]}},"traits":[1437,1505],"content_source_id":3,"version":"1.0","uuid":7192594330416424,"availability":null}},{"table":"trait","row":{"id":2522,"created_at":"2024-04-06T23:37:28.059451+00:00","name":"Radiation","description":"","meta_data":{"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":8799029125441134}},{"table":"trait","row":{"id":1476,"created_at":"2023-12-02T22:37:51.151313+00:00","name":"Poison","description":"An effect with this trait delivers a poison or deals poison damage. An item with this trait is poisonous and might cause an affliction.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=669","book":"Player Core","page":"459"}},"content_source_id":3,"uuid":7663047166217896}},{"table":"trait","row":{"id":1584,"created_at":"2023-12-03T18:55:34.162304+00:00","name":"Water","description":"Effects with the water trait either manipulate or conjure water. Those that manipulate water have no effect in an area without water. Creatures with this trait consist primarily of water or have a magical connection to the element. Planes with this trait are mostly liquid, perhaps with pockets of breathable air.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=732","book":"Player Core","page":"463"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":79251961259262}},{"table":"ability_block","row":{"id":19726,"created_at":"2023-12-13T22:27:16.946946+00:00","operations":null,"name":"Hide","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You huddle behind cover or greater cover or deeper into concealment to become Hidden, rather than Observed. The GM rolls your Stealth check in secret and compares the result to the Perception DC of each creature you're observed by but that you have cover or greater cover against or are [Concealed](link_trait_1841) from. You get a +2 circumstance bonus to your check if you have standard cover (or +4 from greater cover).\n\n**Success** If the creature could see you, you're now Hidden from it instead of Observed. If you were hidden from or Undetected by the creature, you retain that condition.\n\nIf you successfully become hidden to a creature but then cease to have cover or greater cover against it or be concealed from it, you become observed again. You cease being hidden if you do anything except Hide, Sneak, or Step. If you attempt to Strike a creature, the creature remains off-guard against that attack, and you then become observed. If you do anything else, you become observed just before you act unless the GM determines otherwise. The GM might allow you to perform a particularly unobtrusive action without being noticed, possibly requiring another Stealth check.\n\nIf a creature uses Seek to make you observed by it, you must successfully Hide to become hidden from it again.","special":null,"type":"action","meta_data":{"skill":"STEALTH","source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2404","book":"Player Core","page":"244"},"foundry":{"rules":[]}},"traits":[1463,1438],"content_source_id":3,"version":"1.0","uuid":6465165078605128,"availability":null}},{"table":"ability_block","row":{"id":19850,"created_at":"2023-12-14T00:24:29.519666+00:00","operations":null,"name":"Sneak","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You attempt to move to another place while becoming or staying undetected. Stride up to half your Speed. (You can use Sneak while Burrowing, Climbing, Flying, or Swimming instead of Striding if you have the corresponding movement type; you must move at half that Speed.)\n\nAt the end of your movement, the GM rolls your Stealth check in secret and compares the result to the Perception DC of each creature you were Hidden from or Undetected by at the start of your movement. If you have cover or greater cover from the creature throughout your Stride, you gain the +2 circumstance bonus from cover (or +4 from greater cover) to your Stealth check. Because you're moving, the bonus increase from Taking Cover doesn't apply. You don't get to roll against a creature if, at the end of your movement, you neither are [Concealed](link_trait_1841) from it nor have cover or greater cover against it. You automatically become observed by such a creature.\n\n**Success** You're undetected by the creature during your movement and remain undetected by the creature at the end of it.\n\nYou become observed as soon as you do anything other than Hide, Sneak, or Step. If you attempt to Strike a creature, the creature remains Off-Guard against that attack, and you then become observed. If you do anything else, you become observed just before you act unless the GM determines otherwise. The GM might allow you to perform a particularly unobtrusive action without being noticed, possibly requiring another Stealth check. If you speak or make a deliberate loud noise, you become hidden instead of undetected.\n\nIf a creature uses Seek and you become hidden to it as a result, you must Sneak if you want to become undetected by that creature again.\n\n**Failure** A telltale sound or other sign gives your position away, though you still remain unseen. You're hidden from the creature throughout your movement and remain so.\n\n**Critical Failure** You're spotted! You're observed by the creature throughout your movement and remain so. If you're Invisible and were hidden from the creature, instead of being observed you're hidden throughout your movement and remain so.","special":null,"type":"action","meta_data":{"skill":"STEALTH","source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2405","book":"Player Core","page":"245"},"foundry":{"rules":[]}},"traits":[1505,1463,1438],"content_source_id":3,"version":"1.0","uuid":5103370009778602,"availability":null}},{"table":"trait","row":{"id":1630,"created_at":"2023-12-03T19:02:54.235466+00:00","name":"Holy","description":"Effects with the holy trait are tied to powerful magical forces of benevolence and virtue. They often have stronger effects on unholy creatures. Creatures with this trait are strongly devoted to holy causes and often have weakness to [unholy](link_trait_1846). If a creature with weakness to holy uses a holy item or effect, it takes damage from its weakness.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=517","book":"Player Core","page":"457"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":4298428703725190}},{"table":"trait","row":{"id":1453,"created_at":"2023-12-02T22:34:34.973103+00:00","name":"Polymorph","description":"These effects transform the target into a new form. A target can't be under the effect of more than one polymorph effect at a time. If it comes under the effect of a second polymorph effect, the second polymorph effect attempts to [counteract](link_action_27519) the first. If it succeeds, it takes effect, and if it fails, the spell has no effect on that target. Any [Strikes](link_action_19856) specifically granted by a polymorph effect are [magical](link_trait_1504). Unless otherwise stated, polymorph spells don’t allow the target to take on the appearance of a specific individual creature.\n\nIf you take on a battle form with a polymorph spell, the special statistics can be adjusted only by circumstance bonuses, status bonuses, and penalties. Unless otherwise noted, the battle form prevents you from casting spells, speaking, and using most [manipulate](link_trait_1433) actions that require hands. (If there's doubt about whether you can use an action, the GM decides.) You lose your Speeds and gain those of the battle form. Your gear is absorbed into you; the constant abilities of your gear still function, but you can't activate any items.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=670","book":"Player Core","page":"301"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":710137317346589}},{"table":"ability_block","row":{"id":19856,"created_at":"2023-12-14T00:26:07.449536+00:00","operations":null,"name":"Strike","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You attack with a weapon you're wielding or with an unarmed attack, targeting one creature within your reach (for a melee attack) or within range (for a ranged attack). Roll an attack roll using the attack modifier for the weapon or unarmed attack you're using, and compare the result to the target creature's AC to determine the effect.\n\n**Critical Success** You make a damage roll according to the weapon or unarmed attack and deal double damage.\n\n**Success** You make a damage roll according to the weapon or unarmed attack and deal damage.","special":null,"type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2306","book":"Player Core","page":"418"},"foundry":{"rules":[]}},"traits":[1520],"content_source_id":3,"version":"1.0","uuid":2549047613995403,"availability":null}},{"table":"trait","row":{"id":1448,"created_at":"2023-12-02T22:34:10.831185+00:00","name":"Mental","description":"A mental effect can alter the target’s mind. It has no effect on an object or a [mindless](link_trait_2411) creature.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=647","book":"Player Core","page":"458"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3793398752936386}},{"table":"trait","row":{"id":1899,"created_at":"2023-12-14T06:50:16.70839+00:00","name":"Subtle","description":"A spell with the subtle trait can be cast without incantations and doesn't have obvious manifestations.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=522","book":"Player Core","page":"460"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":5272137657224641}},{"table":"item","row":{"id":19837,"created_at":"2025-12-22T19:57:45.555161+00:00","name":"Filtered Rebreather","bulk":"0.1","level":1,"rarity":"COMMON","description":"This armor upgrade supplements your armor’s environmental protections and filters out common contaminants, including protection from most toxic atmospheres.","group":"UPGRADE","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"installed in armor","meta_data":{"bulk":{},"group":"","runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"","dice":1,"extra":"","damageType":""},"source":{"url":"https://2e.aonsrd.com/treasure/47-filtered-rebreather","book":"Starfinder Player Core","page":"268"},"charges":{},"foundry":{},"category":"","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"grade":"COMMERCIAL","slots":[]},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":7839915006113222,"price":{"sp":5},"traits":[4506],"availability":null}},{"table":"ability_block","row":{"id":44905,"created_at":"2025-08-04T15:22:10.721677+00:00","operations":[],"name":"Area Fire","actions":"TWO-ACTIONS","level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"You’re wielding a weapon with the area trait.","access":"","description":"You attempt to hit each creature in a designated area, which has a range equal to the weapon's range increment (for cone or line) or a designated radius of the explosion (for burst). For burst, you can position the center point anywhere within your first range increment. Any creatures in the area must succeed at a basic Reflex save against your class DC plus the tracking value of the weapon (you don't roll an attack roll). This damage is area damage. Creatures who critically fail this save are subject to effects that occur on a critical hit with this weapon, including the weapon's critical specialization effect. Area Fire has an expend equal to the value listed on the weapon.","special":"","type":"action","meta_data":{"source":{"url":"https://2e.aonsrd.com/actions/17-area-fire","book":"Starfinder Player Core","page":"410"}},"traits":[1520,4622],"content_source_id":579,"version":null,"uuid":3371839403077337,"availability":null}},{"table":"trait","row":{"id":1486,"created_at":"2023-12-02T22:40:26.472081+00:00","name":"Emotion","description":"This effect alters a creature’s emotions. Effects with this trait always have the [mental](link_trait_1448) trait as well. Creatures with special training or that have mechanical or artificial intelligence are immune to emotion effects.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=590","book":"Player Core","page":"455"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3036864546165598}},{"table":"trait","row":{"id":1487,"created_at":"2023-12-02T22:40:27.459002+00:00","name":"Fear","description":"Fear effects evoke the emotion of fear. Effects with this trait always have the [mental](link_trait_1448) and [emotion](link_trait_1486) traits as well.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=598","book":"Player Core","page":"456"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":2280463370780525}},{"table":"trait","row":{"id":1481,"created_at":"2023-12-02T22:38:44.663506+00:00","name":"Incapacitation","description":"An ability with this trait can take a character completely out of the fight or even kill them, and it’s harder to use on a more powerful character. If a spell has the incapacitation trait, any creature of more than twice the spell’s level treats the result of their check to prevent being incapacitated by the spell as one degree of success better, or the result of any check the spellcaster made to incapacitate them as one degree of success worse. If any other effect has the incapacitation trait, a creature of higher level than the item, creature, or hazard generating the effect gains the same benefits.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=631","book":"Player Core","page":"457"},"important":true},"content_source_id":3,"uuid":1508160825751788}},{"table":"ability_block","row":{"id":19845,"created_at":"2023-12-14T00:22:00.59033+00:00","operations":null,"name":"Seek","actions":"ONE-ACTION","level":1,"rarity":"COMMON","prerequisites":[],"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You scan an area for signs of creatures or objects, possibly including secret doors or hazards. Choose an area to scan. The GM determines the area you can scan with one Seek action--almost always 30 feet or less in any dimension. The GM might impose a penalty if you search far away from you or adjust the number of actions it takes to Seek a particularly cluttered area.\n\nThe GM attempts a single secret Perception check for you and compares the result to the Stealth DCs of any undetected or hidden creatures in the area, or the DC to detect each object in the area (as determined by the GM or by someone [Concealing the Object](link_action_19615)). A creature you detect might remain hidden, rather than becoming observed, if you're using an imprecise sense or if an effect (such as [invisibility](link_spell_4689)) prevents the subject from being observed.\n\n**Critical Success** Any undetected or hidden creature you critically succeeded against becomes observed by you. You learn the location of objects in the area you critically succeeded against.\n\n**Success** Any undetected creature you suceeded against becomes hidden from you instead of undetected, and any hidden creature you succeeded against becomes observed by you. You learn the location of any object or get a clue to its whereabouts, as determined by the GM.","special":null,"type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2301","book":"Player Core","page":"417"},"foundry":{"rules":[]}},"traits":[1432,1463],"content_source_id":3,"version":"1.0","uuid":2039728856448174,"availability":null}},{"table":"trait","row":{"id":1470,"created_at":"2023-12-02T22:37:00.263254+00:00","name":"Teleportation","description":"Teleportation effects allow you to instantaneously move from one point in space to another. Teleportation does not usually trigger reactions based on movement.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=710","book":"Player Core","page":"462"}},"content_source_id":3,"uuid":5276584614830739}},{"table":"trait","row":{"id":2406,"created_at":"2024-03-30T08:08:34.060381+00:00","name":"Elemental","description":"Elementals are creatures directly tied to an element and native to the elemental planes. Elementals don’t need to breathe.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=587","book":"Player Core","page":"455"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":6512762540686398}},{"table":"trait","row":{"id":1524,"created_at":"2023-12-02T23:32:10.149411+00:00","name":"Air","description":"Effects with the air trait either manipulate or conjure air. Those that manipulate air have no effect in a vacuum or an area without air. Creatures with this trait consist primarily of air or have a magical connection to that element. Planes with this trait consist mostly of open spaces and air with various degrees of turbulence, though they also contain rare islands of floating stone and other elements and energies.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=527","book":"Player Core","page":"452"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3968341994380932}},{"table":"trait","row":{"id":1523,"created_at":"2023-12-02T23:28:42.048767+00:00","name":"Earth","description":"Effects with the earth trait either manipulate or conjure earth. Those that manipulate earth have no effect in an area without earth. Creatures with this trait consist primarily of earth or have a magical connection to that element. Planes with this trait are mostly solid, with caverns and other hollow pockets.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=585","book":"Player Core","page":"455"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":8495630396012560}},{"table":"trait","row":{"id":1680,"created_at":"2023-12-03T19:07:10.274778+00:00","name":"Wood","description":"Effects with the wood trait conjure or manipulate wood. Those that manipulate wood have no effect in an area without wood. Creatures with this trait consist primarily of wood or have a connection to magical wood.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=508","book":"Player Core","page":"463"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":7941158814675420}},{"table":"trait","row":{"id":1458,"created_at":"2023-12-02T22:34:44.520611+00:00","name":"Linguistic","description":"An effect with this trait depends on language comprehension. A linguistic effect that targets a creature works only if the target understands the language you are using.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=642","book":"Player Core","page":"458"},"important":true},"content_source_id":3,"uuid":8640908945330523}},{"table":"trait","row":{"id":1897,"created_at":"2023-12-14T06:45:18.03557+00:00","name":"Sanctified","description":"If you are [holy](link_trait_1630) or [unholy](link_trait_1846), your sanctified actions and spells gain the same trait.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=519","book":"Player Core","page":"113"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":7697026320596128}},{"table":"trait","row":{"id":1556,"created_at":"2023-12-03T18:51:41.851001+00:00","name":"Spirit","description":"Effects with this trait can affect creatures with spiritual essence and might deal spirit damage. A creature with this trait is defined by its spiritual essence. Spirit creatures often lack a material form.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=737","book":"Player Core","page":"461"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":4512353997209738}},{"table":"ability_block","row":{"id":19627,"created_at":"2023-12-13T20:38:46.674225+00:00","operations":null,"name":"Dismiss","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":null,"access":null,"description":"You end an effect that states you can Dismiss it. Dimissing ends the entire effect unless noted otherwise.","special":null,"type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2311","book":"Player Core","page":"419"},"foundry":{"rules":[]}},"traits":[1432,1437],"content_source_id":3,"version":"1.0","uuid":6610017043267456,"availability":null}},{"table":"ability_block","row":{"id":20769,"created_at":"2023-12-14T23:25:55.882053+00:00","operations":[{"id":"85ad67ec-6db0-407a-a46c-a5477825b724","type":"adjValue","data":{"variable":"SENSES_PRECISE","value":"darkvision"}}],"name":"Darkvision","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"A creature with darkvision can see perfectly well in areas of darkness and dim light, though such vision is in black and white only. Some forms of magical darkness, such as a 4th-rank [darkness](link_spell_4552) spell, block normal darkvision.","special":"","type":"sense","meta_data":{"source":{"url":"https://2e.aonprd.com/Familiars.aspx?ID=142","book":"Player Core","page":"259"},"unselectable":true},"traits":[],"content_source_id":3,"version":"1.0","uuid":990708369957964,"availability":null}},{"table":"trait","row":{"id":1492,"created_at":"2023-12-02T22:41:41.564243+00:00","name":"Aura","description":"An aura is an emanation that continually ebbs out from you, affecting creatures within a certain radius. Aura can also refer to the [magical](link_trait_1504) signature of an item.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=542","book":"Player Core","page":"453"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":7373264551834683}},{"table":"trait","row":{"id":2131,"created_at":"2023-12-18T04:11:34.391179+00:00","name":"Olfactory","description":"An olfactory effect can affect only creatures that can smell it. This applies only to olfactory parts of the effect, as determined by the GM.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=664","book":"Player Core","page":"459"}},"content_source_id":3,"uuid":6785598362016579}},{"table":"item","row":{"id":20989,"created_at":"2026-03-02T18:19:51.876392+00:00","name":"Electromag Grenade (Commercial)","bulk":"0.1","level":0,"rarity":"COMMON","description":"**Activate** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> [Area Fire](link_action_44905)\n\n**Critical** glitching 1\n\nThese grenades discharge a shocking field that deals 1d8 [electricity](link_trait_1576) damage in a 5-foot burst with a basic Reflex save. If you have access to the critical specialization effect of grenades, [tech](link_trait_4506) creatures and unattended [tech](link_trait_4506) items that critically fail their saving throw against electromag grenades become glitching.","group":"WEAPON","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"held in 1 hand","meta_data":{"bulk":{},"group":"grenade","range":70,"runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"d8","dice":1,"extra":"","damageType":"electricity"},"source":{"url":"https://2e.aonsrd.com/treasure/101-electromag-grenade","book":"Starfinder Player Core","page":"280"},"charges":{},"foundry":{},"category":"simple","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":5587295779010852,"price":{"sp":10},"traits":[1531,1576,4698,4506],"availability":null}},{"table":"item","row":{"id":21284,"created_at":"2026-03-02T18:23:55.339526+00:00","name":"Flash Grenade (Commercial)","bulk":"0.1","level":0,"rarity":"COMMON","description":"**Activate** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> [Area Fire](link_action_44905)\n\nA flash grenade unleashes a blast of bright light that requires creatures in a 5-foot burst to attempt a Fortitude save. On a failure, the creature is dazzled for 1 round.","group":"WEAPON","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"held in 1 hand","meta_data":{"bulk":{},"group":"grenade","range":70,"runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"","dice":"","extra":"","damageType":""},"source":{"url":"https://2e.aonsrd.com/treasure/102-flash-grenade","book":"Starfinder Player Core","page":"280"},"charges":{},"foundry":{},"category":"simple","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":211815450133511,"price":{"sp":10},"traits":[1531,4698,1517,4506,1479],"availability":null}},{"table":"item","row":{"id":21047,"created_at":"2026-03-02T18:20:53.924586+00:00","name":"Frag Grenade (Commercial)","bulk":"0.1","level":0,"rarity":"COMMON","description":"**Activate** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> [Area Fire](link_action_44905)\n\n**Critical** 1 persistent bleed damage\n\nThese fragmentary grenades explode in a cloud of shrapnel and deal 1d8 piercing damage in a 5-foot burst with a basic Reflex save.","group":"WEAPON","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"held in 1 hand","meta_data":{"bulk":{},"group":"grenade","range":70,"runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"d8","dice":1,"extra":"","damageType":"piercing"},"source":{"url":"https://2e.aonsrd.com/treasure/103-frag-grenade","book":"Starfinder Player Core","page":"280"},"charges":{},"foundry":{},"category":"simple","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":1148209103214232,"price":{"sp":10},"traits":[1531,4698,4506],"availability":null}},{"table":"item","row":{"id":21219,"created_at":"2026-03-02T18:22:51.817178+00:00","name":"Incendiary Grenade (Commercial)","bulk":"0.1","level":0,"rarity":"COMMON","description":"**Activate** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> [Area Fire](link_action_44905)\n\n**Critical** 5 feet\n\nThese grenades use an ignited chemical to explode in a blast of intense heat and deal 1d8 [fire](link_trait_1542) damage in a 5-foot burst with a basic Reflex save. If you have access to the critical specialization effect of grenades, creatures who critically fail their saving throw against incendiary grenades are knocked away from the grenade.","group":"WEAPON","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"held in 1 hand","meta_data":{"bulk":{},"group":"grenade","range":70,"runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"d8","dice":1,"extra":"","damageType":"fire"},"source":{"url":"https://2e.aonsrd.com/treasure/104-incendiary-grenade","book":"Starfinder Player Core","page":"281"},"charges":{},"foundry":{},"category":"simple","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":3789568931429774,"price":{"sp":10},"traits":[1531,1542,4698,4506],"availability":null}},{"table":"item","row":{"id":21387,"created_at":"2026-03-02T18:26:40.361237+00:00","name":"Smoke Grenade (Commercial)","bulk":"0.1","level":0,"rarity":"COMMON","description":"**Activate** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> [Area Fire](link_action_44905)\n\nThis grenade unleashes a cloud of concealing smoke in a 5-foot burst. Creatures within the area have the concealed condition, and all other creatures are concealed to them. The smoke lasts for 1 minute or until dissipated by a strong wind or similar effect.","group":"WEAPON","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"held in 1 hand","meta_data":{"bulk":{},"group":"grenade","range":70,"runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"","dice":"","extra":"","damageType":""},"source":{"url":"https://2e.aonsrd.com/treasure/105-smoke-grenade","book":"Starfinder Player Core","page":"281"},"charges":{},"foundry":{},"category":"simple","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":3174761647355076,"price":{"sp":10},"traits":[1531,4698,4506],"availability":null}},{"table":"trait","row":{"id":1904,"created_at":"2023-12-14T06:59:35.313327+00:00","name":"Death","description":"An effect with the death trait kills you immediately if it reduces you to 0 HP. Some death effects can bring you closer to death or slay you outright without reducing you to 0 HP.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=571","book":"Player Core","page":"454"},"important":true},"content_source_id":3,"uuid":2476643980238200}},{"table":"item","row":{"id":19684,"created_at":"2025-12-06T00:37:56.712084+00:00","name":"Laser Pistol","bulk":"1","level":0,"rarity":"COMMON","description":"This compact pistol is the most popular sidearm in the Pact Worlds thanks to its reliability, durability, and affordability. Most common laser pistols have a lightweight polycarbon body ending in a long, slim barrel.","group":"WEAPON","hands":"1","size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"laser","range":40,"runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"d6","dice":1,"extra":"","damageType":"fire"},"reload":"1","source":{"url":"https://2e.aonsrd.com/equipment/weapons/40-laser-pistol","book":"Starfinder Player Core","page":"265"},"charges":{},"foundry":{},"category":"simple","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"grade":"COMMERCIAL","slots":[],"usage":2,"capacity":"10 charges"},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":6577036545124454,"price":{"sp":30},"traits":[4506],"availability":null}},{"table":"item","row":{"id":19694,"created_at":"2025-12-06T01:13:05.010069+00:00","name":"Laser Rifle","bulk":"2","level":0,"rarity":"COMMON","description":"These dependable, mass-produced rifles shoot concentrated beams of energy out of square-shaped barrels. The universal standard Pact Worlds model is highly modifiable and designed to function with a variety of accessories and upgrades, with wielders adapting the laser rifle to their preferences and even kit-bashing it into a nearly unrecognizable weapon.","group":"WEAPON","hands":"2","size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"laser","range":100,"runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"d8","dice":1,"extra":"","damageType":"fire"},"reload":"1","source":{"url":"https://2e.aonsrd.com/equipment/weapons/41-laser-rifle","book":"Starfinder Player Core","page":"265"},"charges":{},"foundry":{},"category":"simple","material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"grade":"COMMERCIAL","slots":[],"usage":2,"capacity":"10 charges"},"unselectable":false},"operations":[],"content_source_id":579,"version":"1.0","uuid":6535666046694857,"price":{"sp":45},"traits":[4506],"availability":null}},{"table":"trait","row":{"id":2938,"created_at":"2024-04-20T06:47:45.400828+00:00","name":"Plant","description":"[Magical](link_trait_1504) effects with this trait manipulate or conjure plants or plant matter in some way. Effects that manipulate plants have no effect in an area with no plants.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=668","book":"Player Core","page":"459"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":339889839350251}},{"table":"spell","row":{"id":4746,"created_at":"2024-03-23T20:57:17.579291+00:00","name":"One with Plants","rank":2,"traditions":["primal"],"rarity":"COMMON","cast":"TWO-ACTIONS","traits":[1432,1433,1654,1453,1680],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"10 minutes or 8 hours","description":"You can either transform into a plant or merge with plant matter. While transformed, you can't move or affect anything outside the plant, but you can cast spells as long as they don't require line of effect beyond the plant. You can Dismiss this spell.\n\n*   **Merge with Plants** The spell's duration is 10 minutes. While casting the spell, you must touch a plant with enough volume to fit you and your possessions or the spell is disrupted. While merged, you can hear, but not see, what's going on outside the plant. If the plant takes damage while you're inside it, you're expelled from the plant and take 10d6 damage. _Magic passage_ expels you without dealing damage. The spell ends if you're ever outside the plant.\n*   **Turn into a Plant** The spell's duration is 8 hours. You become a Large plant—typically a tree. Perception checks don't reveal your true nature, but a successful Nature or Survival check against your spell DC reveals that you appear to be a plant that is strangely new to the area. While in this form, you can observe everything around you, using your normal senses. As a plant, your AC is 20, and only status bonuses, status penalties, circumstance bonuses, and circumstance penalties affect you. Any successes and critical successes you roll on Reflex saves are failures","meta_data":{"damage":[],"source":{"url":"https://2e.aonprd.com/Spells.aspx?ID=1618","book":"Player Core","page":"347"},"foundry":{"rules":[],"is_focus":false}},"content_source_id":3,"version":"1.0","uuid":2272578972804192,"heightened":{},"availability":null}},{"table":"trait","row":{"id":1590,"created_at":"2023-12-03T18:56:32.850765+00:00","name":"Scrying","description":"A scrying effect lets you see, hear, or otherwise get sensory information from a distance using a sensor or apparatus, rather than your own eyes and ears.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=689","book":"Player Core","page":"460"}},"content_source_id":3,"uuid":570162919720558}},{"table":"trait","row":{"id":1456,"created_at":"2023-12-02T22:34:38.879756+00:00","name":"Morph","description":"Effects that slightly alter a creature's form have the morph trait. Any [Strikes](link_action_19856) specifically granted by a morph effect are [magical](link_trait_1504). You can be affected by multiple morph spells at once, but if you morph the same body part more than once, the second morph effect attempts to [counteract](link_action_27519) the first (in the same manner as two [polymorph](link_trait_1453) effects, described in that trait). Your morph effects might also end if you are polymorphed and the polymorph effect invalidates or overrides your morph effect. The GM determines which morph effects can be used together and which can't.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=657","book":"Player Core","page":"301"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":3327278025830287}},{"table":"ability_block","row":{"id":19853,"created_at":"2023-12-14T00:25:25.366071+00:00","operations":null,"name":"Step","actions":"ONE-ACTION","level":null,"rarity":"COMMON","prerequisites":null,"frequency":null,"cost":null,"trigger":null,"requirements":"Your Speed is at least 10 feet.","access":null,"description":"You carefully move 5 feet. Unlike most types of movement, Stepping doesn't trigger reactions, such as [Reactive Strike](link_class-feature_19201), that can be triggered by move actions or upon leaving or entering a square.\n\nYou can't Step into difficult terrain, and you can't Step using a Speed other than your land Speed.","special":null,"type":"action","meta_data":{"source":{"url":"https://2e.aonprd.com/Actions.aspx?ID=2304","book":"Player Core","page":"418"},"foundry":{"rules":[]}},"traits":[1437,1505],"content_source_id":3,"version":"1.0","uuid":567734121479914,"availability":null}},{"table":"trait","row":{"id":4513,"created_at":"2025-06-27T23:41:45.164507+00:00","name":"Cosmic","description":"Creatures with the cosmic trait don’t need to breathe while in space or a vacuum and are immune to the harmful environmental effects of being in space.","meta_data":{"source":{"url":"https://2e.aonsrd.com/traits/52-cosmic","book":"Starfinder Player Core","page":"445"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":579,"uuid":3337560781590447}},{"table":"trait","row":{"id":2584,"created_at":"2024-04-19T02:01:06.796453+00:00","name":"Incarnate","description":"A spell with the incarnate trait is similar in theme to spells that summon creatures, but it doesn’t conjure a [minion](link_trait_2527) with the [summoned](link_trait_2134) trait. Instead, when summoned, the incarnate creature takes its Arrive action when you finish [Casting the Spell](link_action_19611). At the end of your next turn, the incarnate creature can either [Step](link_action_19853), [Stride](link_action_19855), or take the action for another movement type it has (such as [Climb](link_action_19612) or [Burrow](link_action_19609)), and then takes its Depart action. The spell then ends. The names of specific Arrive and Depart actions are listed in italics after the word “Arrive” or “Depart” respectively, along with any traits.\n\nA creature summoned by an incarnate spell acts in your interests, directs its effects away from you and your allies as much as possible, and might listen to your requests, but ultimately makes its own decisions. If the spell indicates that the incarnate makes a decision, the GM determines what the incarnate would do. It might even become more inclined to do precisely as you wish over multiple summonings.\n\nThe incarnate is not fully a creature. It can’t take any other actions, nor can it be targeted or harmed by [Strikes](link_action_19856), spells, or other effects unless they would be able to target or end a spell effect (such as [dispel magic](link_spell_4572)). It has a size for the purposes of determining its placement for effects, but it doesn’t block movement. If applicable, its effects use your spell DCs and spell attack modifier.","meta_data":{"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":15,"uuid":3690091311596588}},{"table":"trait","row":{"id":4533,"created_at":"2025-07-06T16:51:04.452923+00:00","name":"Traversal","description":"These abilities can easily be adapted for other forms of movement. An action with this trait includes oneor more [Stride](link_action_19855) actions but can be easily adapted to other modes of movement. You can substitute a [Burrow](link_action_19609), [Climb](link_action_19612), [Fly](link_action_19721), or [Swim](link_action_19859) action in place of any [Stride](link_action_19855) actions if you have the corresponding movement type. (Any adjustments to the [Stride](link_action_19855), such as gaining a bonus or penalty to your Speed, still apply to the substituted movement type.)","meta_data":{"source":{"url":"https://2e.aonsrd.com/traits/185-traversal","book":"Starfinder Player Core","page":"455"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":579,"uuid":4894144806914806}},{"table":"trait","row":{"id":2133,"created_at":"2023-12-18T04:35:00.571232+00:00","name":"Possession","description":"Effects with this trait allow a creature to project its mind and spirit into a target. A creature immune to [mental](link_trait_1448) effects can't use a possession effect. While possessing a target, a possessor's true body is unconscious (and can't wake up normally), unless the possession effect allows the creature to physically enter the target. Whenever the target takes damage, the possessor takes half that amount of damage as mental damage.\n\nA possessor loses the benefits of any of its active spells or abilities that affect its physical body, though it gains the benefits of the target's active spells and abilities that affect their body. A possessor can use any of the target's abilities that are purely physical, and it can't use any of its own abilities except spells and purely mental abilities. The GM decides whether an ability is purely physical or purely mental. A possessor uses the target's attack modifier, AC, Fortitude save, Reflex save, Perception, and physical skills, and its own Will save, mental skills, spell attack modifier, and spell DC; benefits of [invested](link_trait_1527) items apply where relevant (the possessor's invested items apply when using its own values, and the target's invested items apply when using the target's values). A possessor gains no benefit from casting spells that normally affect only the caster, since it isn't in its own body. The possessor must use its own actions to make the possessed creature act.\n\nIf a possessor reaches 0 Hit Points through any combination of damage to its true body and mental damage from the possession, it is knocked out as normal and the possession immediately ends. If the target reaches 0 Hit Points first, the possessor can either fall unconscious with the body and continue the possession or end the effect as a free action and return to its body. If the target dies, the possession ends immediately, and the possessor is stunned for 1 minute.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=671","book":"Player Core","page":"459"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":8071503302990726}},{"table":"trait","row":{"id":5236,"created_at":"2026-10-08T04:38:40.516476+00:00","name":"Station","description":"Actions with the station trait can only be performed while helming a battle station. Most are granted by a specific battle station.","meta_data":{"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":900,"uuid":2341035972402734}},{"table":"trait","row":{"id":1520,"created_at":"2023-12-02T23:28:07.861361+00:00","name":"Attack","description":"An ability with this trait involves an attack. For each attack you make beyond the first on your turn, you take a multiple attack penalty.","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=540","book":"Player Core","page":"452"},"important":true},"content_source_id":3,"uuid":1285342290589006}},{"table":"trait","row":{"id":1858,"created_at":"2023-12-13T08:04:05.408784+00:00","name":"Cantrip","description":"A spell you can cast at will that is automatically heightened to half your level rounded up.","meta_data":null,"content_source_id":3,"uuid":7837841754363754}},{"table":"trait","row":{"id":4670,"created_at":"2025-08-10T21:09:14.049044+00:00","name":"Powered","description":"This melee weapon uses a battery. You can activate or deactivate a powered weapon with an Interact action or as part of drawing or stowing it. This weapon comes with a commercial battery installed and uses 1 charge per day (rather than 1 charge per attack). If you try to attack with a powered weapon that's out of charges or deactivated, it functions as an improvised weapon. A modular (powered) weapon activates or deactivates when it switches between its modular configurations.","meta_data":{"source":{"url":"https://2e.aonsrd.com/traits/142-powered","book":"Starfinder Player Core","page":"256"},"important":true,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":false,"archetype_trait":false,"companion_type_trait":false,"versatile_heritage_trait":false},"content_source_id":579,"uuid":4922470314682877}},{"table":"trait","row":{"id":2410,"created_at":"2024-03-30T08:08:50.401321+00:00","name":"Construct","description":"A construct is an artificial creature empowered by a force other than [vitality](link_trait_1478) or [void](link_trait_1485).","meta_data":{"source":{"url":"https://2e.aonprd.com/Traits.aspx?ID=563","book":"Player Core","page":"454"},"important":false,"class_trait":false,"unselectable":false,"ancestry_trait":false,"creature_trait":true,"archetype_trait":false,"versatile_heritage_trait":false},"content_source_id":3,"uuid":1662690838306083}},{"table":"item","row":{"id":9252,"created_at":"2024-03-24T22:44:19.105898+00:00","name":"Fist","bulk":"0","level":0,"rarity":"COMMON","description":"_Sometimes, the only way you can make someone listen is with your fist._","group":"WEAPON","hands":"1","size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"brawling","runes":{"property":[]},"damage":{"die":"d4","dice":1,"extra":"","damageType":"bludgeoning"},"hp_max":0,"source":{"url":"https://2e.aonprd.com/Weapons.aspx?ID=356","book":"Player Core","page":"277"},"charges":{},"foundry":{},"category":"unarmed_attack","hardness":0,"material":{},"quantity":1,"image_url":"","is_shoddy":false,"starfinder":{"slots":[]},"unselectable":true,"broken_threshold":0},"operations":[],"content_source_id":1,"version":"1.0","uuid":4222677782720902,"price":{},"traits":[1569,1570,1571,2398],"availability":null}}],"prior_rows":[{"name":"Bugfix","rank":0,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1858,1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 creature or object with the glitching condition","duration":"","description":"You release a magically self-editing line of code into the target, tackling the root cause of any technical failings afflicting it. You attempt to [counteract](link_action_27519) the glitching condition affecting the target. Regardless of the result, the target becomes immune to *[bugfix](link_spell_900000507)* for 1 minute.","heightened":{"text":[],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"149","url":"https://2e.aonsrd.com/spells/507-bugfix"}},"content_source_id":900,"version":"1.0","uuid":299866193306417},{"name":"Detect Technology","rank":0,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1858,1432,1508,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":"30-foot emanation","targets":"","duration":"","description":"You send out a pulse of magic that detects the presence of technology, including creatures, hazards, and objects with the [tech](link_trait_4506) trait. You receive no information beyond the presence or absence of technology. You can choose to ignore technology you're fully aware of, such as the technology of you and your allies and the ship you're traveling in.","heightened":{"text":[{"amount":"(3rd)","text":"You learn the level or rank of the most powerful technology, as determined by the GM."},{"amount":"(4th)","text":"As 3rd rank, but you also pinpoint the source of the highest-level or highest-ranked technology. Like for an imprecise sense, you don't learn the exact location but can narrow down the source to within a 5-foot cube (or the nearest if larger than that)."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"152","url":"https://2e.aonsrd.com/spells/508-detect-technology"}},"content_source_id":900,"version":"1.0","uuid":6023438549940619},{"name":"Emoticon","rank":0,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1520,1858,1432,1560,1433],"defense":"AC","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"1 creature","duration":"","description":"You unleash a string of emoticons that bash against a creature. Make a spell attack roll against the target's AC, dealing 2d4 bludgeoning or [force](link_trait_1560) damage (chosen when you [Cast the Spell](link_action_19611)).","heightened":{"text":[{"amount":"(+1)","text":"The damage increases by 1d4."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/437-emoticon"}},"content_source_id":900,"version":"1.0","uuid":1011056868991540},{"name":"Linked Sight","rank":0,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"ONE-ACTION","traits":[1858,1432,1433,1590],"defense":null,"cost":"","trigger":null,"requirements":"You have a scope, goggles, or some other optical tool, used as a locus.","range":"30 feet","area":null,"targets":"","duration":"5 minutes","description":"You toss the required locus to a point in range, imbuing the optic tool with a connection to your own vision. For the duration, the locus can see in all directions with your normal visual senses, though it treats sight as an imprecise sense past 15 feet. You can [Sustain](link_action_19858) the spell to switch between seeing through the locus or through your standard vision.","heightened":{"text":[{"amount":"(+1)","text":"The duration of the spell is increased by 5 minutes, and the range past which the locus's sight becomes imprecise is increased by 5 feet."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/457-linked-sight"}},"content_source_id":900,"version":"1.0","uuid":2805567295624203},{"name":"Junk Armor","rank":1,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"10 minutes","description":"You create light, medium, or heavy armor out of junk that you immediately don. You lose the benefits of any armor you were already wearing when you [Cast this Spell](link_action_19611), including any upgrades in that armor. You can create any common commercial grade armor, and it gains the [noisy](link_trait_1582) and [tech](link_trait_4506) traits if it doesn't have them already. It can't be made of any special materials.\n\nThe armor has one fewer upgrade slot than usual. When you [Cast this Spell](link_action_19611), you can automatically [Install](link_action_46744) any upgrades you're holding in your hands as a locus into any upgrade slots the armor has.","heightened":{"text":[{"amount":"(2nd)","text":"You can create tactical armor."},{"amount":"(5th)","text":"You can create advanced armor."},{"amount":"(6th)","text":"You can create superior armor."},{"amount":"(8th)","text":"You can create elite armor."},{"amount":"(9th)","text":"You can create ultimate armor."},{"amount":"(10th)","text":"You can create paragon armor."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"155","url":"https://2e.aonsrd.com/spells/448-junk-armor"}},"content_source_id":900,"version":"1.0","uuid":5420111739556292},{"name":"Junk Restraints","rank":1,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433],"defense":"Reflex","cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 creature","duration":"","description":"Pieces of junk clamp around the target's limbs, locking them in place like a series of makeshift manacles. The target must attempt a Reflex saving throw.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature is suppressed for 1 round.\n\n**Failure** The creature is clumsy 1 and suppressed for 1 hour.\n\n**Critical Failure** As failure, but the creature is also restrained and drops all items it's holding in its space. The restraints' [Force Open](link_action_19722) and [Escape](link_action_19632) DCs are equal to your spell DC. A creature can attack the restraints in an attempt to break its grip. The restraints have AC equal to your spell DC, Hardness 5, and 20 Hit Points. Destroying, [Forcing Open](link_action_19722), or [Escaping](link_action_19632) from the restraints ends the spell.","heightened":{"text":[{"amount":"(3rd)","text":"The junk has Hardness 8 and 66 Hit Points."},{"amount":"(5th)","text":"The junk has Hardness 8 and 88 Hit Points."},{"amount":"(8th)","text":"The junk has Hardness 10 and 100 Hit Points."}],"data":{}},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"156","url":"https://2e.aonsrd.com/spells/451-junk-restraints"}},"content_source_id":900,"version":"1.0","uuid":5366499937587165}],"rows":[{"name":"Alchemical Shot","rank":1,"uuid":1290610822205816,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,2132],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":"15-foot cone","targets":"","duration":"","description":"You transmute scrap metal into a shotgun blast of high-purity precious metals. Creatures in the area take 1d8 piercing damage with a basic Reflex save. The damage counts as [cold iron](link_item_15059) or [silver](link_item_15062) (chosen when you [Cast the Spell](link_action_19611)). The spell gains no benefits from the chosen material except for determining immunities, resistances, and weaknesses.","heightened":{"data":{},"text":[{"amount":"(3rd)","text":"The damage increases to 3d8."},{"amount":"(5th)","text":"The damage increases to 6d8, and you can also choose to have the damage count as [adamantine](link_item_15064), [cold iron](link_item_15059), or [silver](link_item_15062)."},{"amount":"(7th)","text":"As 5th-rank, and increase the damage to 9d8."},{"amount":"(9th)","text":"The damage increases to 12d8, and you can choose to have the damage count as any precious metal."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"j25dWcmRG1vv5DJc","path":"packs/sf2e/spells/spells/rank-1/alchemical-shot.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"c79c56f92d543732cec73323b696928b46e7872fd1584a1a1a0e82f7d8e746a2","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"148","url":"https://2e.aonsrd.com/spells/406-alchemical-shot"}},"content_source_id":900,"version":"1.0"},{"name":"Angelic Signal","rank":3,"uuid":2083440659933283,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"REACTION","traits":[1432],"defense":"Will","cost":"","trigger":"An ally is targeted by an attack from a [tech](link_trait_4506) creature or a creature wielding a weapon with the [tech](link_trait_4506) trait.","requirements":null,"range":"30 feet","area":null,"targets":"the triggering creature","duration":"","description":"An angelic messenger swarms the attacking creature with nonsensical data derived from prayers emanating from their [tech](link_trait_4506) devices. The target must attempt a Will saving throw. Regardless of the result, the target becomes immune to _[angelic signal](link_spell_{{allocated:2083440659933283}})_ for 10 minutes.\n\n**Critical Success** The target is unaffected.\n\n**Success** The target takes a –1 status penalty to all attack and damage rolls with [tech](link_trait_4506) weapons until the end of the turn.\n\n**Failure** The target takes a –2 status penalty to all attack and damage rolls with [tech](link_trait_4506) weapons until the end of the turn.\n\n**Critical Failure** The target takes a –3 status penalty to all attack and damage rolls with [tech](link_trait_4506) weapons until the end of the turn.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"ftPpuRM57GD3SDBQ","path":"packs/sf2e/spells/spells/rank-3/angelic-signal.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"46029a19305d79a2ef7262070d6d48af79ee4ed5692ce2e130a7f97f73da3751","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"148","url":"https://2e.aonsrd.com/spells/407-angelic-signal"}},"content_source_id":900,"version":"1.0"},{"name":"Biomechanical Symbiosis","rank":2,"uuid":3779447928559651,"traditions":["divine","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1576,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"touch","area":null,"targets":"1 creature with the [tech](link_trait_4506) trait or with a [tech](link_trait_4506) augmentation","duration":"1 minute","description":"You redirect magical power through your target's circuitry, stimulating hybrid magical and technological healing. The target regains 2 Hit Points immediately and the first time each round for the duration of the spell. Whenever the target takes [electricity](link_trait_1576) damage or rolls a flat check due to the glitching condition, it also regains 2 Hit Points.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The Hit Points regained increase by 2."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"a8t4GpinUPJE0oLO","path":"packs/sf2e/spells/spells/rank-2/biomechanical-symbiosis.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"d9b85b074752b31d6e609240e80b0eaba3fa3e394bbd72270fc676a8b4f3ee72","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"148","url":"https://2e.aonsrd.com/spells/409-biomechanical-symbiosis"}},"content_source_id":900,"version":"1.0"},{"name":"Blinding Emoji","rank":5,"uuid":352877985552298,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1517,1433,1479],"defense":"Fortitude","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":"20-foot burst","targets":"","duration":"sustained up to 1 minute","description":"You create an emoji so bright that it wears sunshades to protect itself from its own light. Creatures in the area when you [Cast the Spell](link_action_19611) or that start their turn in the area must attempt a Fortitude saving throw. When you [Sustain](link_action_19858) the spell, you can move the area up to 30 feet.\n\n**Critical Success** The creature is unaffected and temporarily immune to _[blinding emoji](link_spell_{{allocated:352877985552298}})_ for 1 minute.\n\n**Success** The creature is unaffected.\n\n**Failure** The creature is blinded until the end of its next turn.\n\n**Critical Failure** The creature is blinded for 1 minute.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"ZSlXevjqvcApnO36","path":"packs/sf2e/spells/spells/rank-5/blinding-emoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"d4d2eea72898f9653daa6beed97e89f7da86a99d8da3703be38fc16ad6e2ee03","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"148","url":"https://2e.aonsrd.com/spells/410-blinding-emoji"}},"content_source_id":900,"version":"1.0"},{"name":"Bolster Weapon","rank":2,"uuid":4294858959700632,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"1 [powered](link_trait_4670) melee weapon","duration":"1 minute","description":"You use some of your magic to empower a weapon, creating an idealized version of the armament. When you [Cast this Spell](link_action_19611), choose one of the following traits: [agile](link_trait_1569), [backswing](link_trait_1619), [forceful](link_trait_1598), [reach](link_trait_1573), or [sweep](link_trait_1562). The target weapon gains the chosen trait.","heightened":{"data":{},"text":[{"amount":"(5th)","text":"You can target up to five weapons, choosing a trait for each weapon."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"GdvESca5RRPKA2Ji","path":"packs/sf2e/spells/spells/rank-2/bolster-weapon.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"7e658af8844e6c5214f19a47fadd14258b0f0658eaeb4012bbdee2b6bce91057","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"148","url":"https://2e.aonsrd.com/spells/411-bolster-weapon"}},"content_source_id":900,"version":"1.0"},{"name":"Bombarding Emojis","rank":4,"uuid":3594292142246612,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1560,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"100 feet","area":"10-foot burst","targets":"","duration":"sustained up to 1 minute","description":"You conjure a barrage of emojis that rain from the sky. Creatures in the area take 6d8 [force](link_trait_1560) damage (basic Reflex save). When you [Cast the Spell](link_action_19611) and the first time you [Sustain](link_action_19858) it each subsequent round, each creature in the area takes 6d8 [force](link_trait_1560) damage (basic Reflex save).","heightened":{"data":{},"text":[{"amount":"(+2)","text":"The damage increases by 3d8."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"vuiUvfh3ptO9gnDI","path":"packs/sf2e/spells/spells/rank-4/bombarding-emojis.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"d9876f8d2420dc7c82af507443f1634c2f07955d8eb8354b3c4f8d8855e5222a","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"148","url":"https://2e.aonsrd.com/spells/412-bombarding-emojis"}},"content_source_id":900,"version":"1.0"},{"name":"Boot Loop","rank":7,"uuid":2897123612839413,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1469,1432,1433,1484],"defense":"Fortitude","cost":"","trigger":null,"requirements":null,"range":"","area":"60-foot cone","targets":"","duration":"","description":"You deliver a perfectly crafted command with the power of your voice, triggering mass reboots and shaking bodies apart. You deal 10d8 [sonic](link_trait_1484) damage to all creatures in the area. Each creature must attempt a Fortitude save.\n\n**Critical Success** The target is unaffected.\n\n**Success** The target takes half damage.\n\n**Failure** The target takes full damage. Creatures with the [tech](link_trait_4506) trait become glitching 1, and creatures without the [tech](link_trait_4506) trait are deafened for 1 round.\n\n**Critical Failure** The target takes double damage. Creatures with the [tech](link_trait_4506) trait become glitching 2, and creatures without the [tech](link_trait_4506) trait are deafened for 1 minute.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"qwVddukwlfbtm1Ti","path":"packs/sf2e/spells/spells/rank-7/boot-loop.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"ed2a15c2db1a04bae0e73fcc034ffe7427a16b7ed6f0c23748cf07361389e79a","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"149","url":"https://2e.aonsrd.com/spells/413-boot-loop"}},"content_source_id":900,"version":"1.0"},{"name":"Build Booster Ring","rank":4,"uuid":2203944361792065,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"","duration":"1 round","description":"You use magical [tech](link_trait_4506) to create a ring that's 1 inch thick, 10 feet wide, and 10 feet high. You must create the ring in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. The ring contains a ripple in space-time that amplifies those that pass through it. Creatures or vehicles that move through the ring gain a +30-foot status bonus to their Speeds until the end of the turn.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"yIRR3rgI0gtNrKQf","path":"packs/sf2e/spells/spells/rank-4/build-booster-ring.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"8046770717f7b2f91edf85b0f9474a59d8ce179e572de8292b466a30271035cf","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"149","url":"https://2e.aonsrd.com/spells/414-build-booster-ring"}},"content_source_id":900,"version":"1.0"},{"name":"Build Bulkhead Stronghold","rank":10,"uuid":7536588745905164,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":"10-foot emanation","targets":"","duration":"1 minute","description":"You rapidly conjure a small technological stronghold that surrounds you, and all enemies are pushed to the nearest safe empty space outside of the area. The stronghold has AC 10, Hardness 10, and 150 Hit Points, and it's immune to critical hits and precision damage. It has the [tech](link_trait_4506) trait. Several large robotic legs sprout from the stronghold, allowing it to move with you, constantly keeping you at its center. The stronghold automatically opens to allow allies to enter while enemies are kept out. When you move in such a way that enemies would enter the area, they're instead pushed to the nearest safe empty space. Enemies can't enter the stronghold. Allies within the stronghold gain the benefits of standard cover, and all allies who start their turn within the stronghold gain 10 temporary Hit Points that last for the spell's duration.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"fD644qK2ftpFhebf","path":"packs/sf2e/spells/spells/rank-10/build-bulkhead-stronghold.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"1b1af79fae882db496ab4d2a98e4b4ca9231d4850226aea3091763871d5de50f","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"149","url":"https://2e.aonsrd.com/spells/415-build-bulkhead-stronghold"}},"content_source_id":900,"version":"1.0"},{"name":"Build Healing Station","rank":3,"uuid":5762570506581385,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1442,1433,1478],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"1 minute","description":"You deploy a station in an adjacent empty space that floats in the air, fueling combatants and keeping them ready to fight on. The station is Small, visibly the source of the healing, has AC 10 and 30 Hit Points, and is immune to critical hits and precision damage. The station also has the [tech](link_trait_4506) trait. Anytime you or an ally ends a turn adjacent to the healing station, the adjacent character heals for 5 Hit Points and gains a +1 status bonus to saving throws for 1 round.","heightened":{"data":{},"text":[{"amount":"(+3)","text":"The station's Hit Points increase by 30, and the healing increases by 5."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"yG9AUj9Krcrx7U87","path":"packs/sf2e/spells/spells/rank-3/build-healing-station.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"ab0cf17079d93bc9501e46a50455767cdd912ff5533a2fdecc0142ef590c2403","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"150","url":"https://2e.aonsrd.com/spells/416-build-healing-station"}},"content_source_id":900,"version":"1.0"},{"name":"Build Sentries","rank":3,"uuid":2567290893928867,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"ONE-TO-THREE-ACTIONS","traits":[1432,1542,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"","duration":"1 hour","description":"You deploy sentry turrets to attack intruders. For each action you spend [Casting the Spell](link_action_19611), you deploy a sentry turret into an empty space within range, attaching itself to any solid surface. These sentry turrets are Small and visibly dangerous. They have AC 10, Hardness 3, and 15 Hit Points and are immune to critical hits and precision damage. The sentries also have the [tech](link_trait_4506) trait. Whenever a visible creature that isn't [Avoiding Notice](link_action_21146), [Hiding](link_action_19726), or [Sneaking](link_action_19850) comes within 15 feet of a sentry turret, you receive a ping and a small video feed of the creature on your [comm unit](link_item_18663). Once per round on subsequent turns, you can [Interact](link_action_19733) with your [comm unit](link_item_18663) to Command any number of sentry turrets to each fire a beam of energy at a creature within 30 feet of the sentry turret, dealing 2d6 [fire](link_trait_1542) damage (basic Reflex save). A creature can only be targeted by a single sentry turret each turn, even if it's within range of multiple sentries.","heightened":{"data":{},"text":[{"amount":"(+2)","text":"The Hit Points of each sentry turret increase by 10, and the damage increases by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"tlGugw7XE5xYUsxZ","path":"packs/sf2e/spells/spells/rank-3/build-sentries.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"0b97181af8da42057acc658793b254bbb227ec73286068609c0d8b9239712985","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"150","url":"https://2e.aonsrd.com/spells/417-build-sentries"}},"content_source_id":900,"version":"1.0"},{"name":"Build Shield Generator","rank":4,"uuid":3144637894654694,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":"60 feet","targets":"","duration":"1 minute","description":"You bind together magic and science to create a shield generator in an empty adjacent space. The generator is Small, visibly the source of the shields, has AC 10 and 40 Hit Points, and is immune to critical hits and precision damage. The generator also has the [tech](link_trait_4506) trait. This generator provides a small, shimmering light that covers you and all allies within 60 feet, granting a +1 status bonus to AC, as well as resistance 4 to [acid](link_trait_1528), [cold](link_trait_1519), [electricity](link_trait_1576), [fire](link_trait_1542), [force](link_trait_1560), and [sonic](link_trait_1484) damage. If the generator is destroyed, the spell ends.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The generator's Hit Points increase by 10, and the resistance granted by the generator increases by 1."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"q0JMsrMuk19oLzXY","path":"packs/sf2e/spells/spells/rank-4/build-shield-generator.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"0b136992cf4fbc6bf01f87cd2d22c19ee6204beeefe3d66f50832a0fbdb05b15","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"150","url":"https://2e.aonsrd.com/spells/418-build-shield-generator"}},"content_source_id":900,"version":"1.0"},{"name":"Burstmoji","rank":4,"uuid":8914394946772363,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1542,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"200 feet","area":"20-foot burst","targets":"","duration":"1 minute","description":"You create an emoji of an explosion that erupts into a mass of flames. Creatures in the area take 6d6 [fire](link_trait_1542) damage (basic Reflex save), and the area becomes difficult and hazardous terrain for the duration. Creatures that start their turn in the area or move through a square in the area take 5 [fire](link_trait_1542) damage.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The initial [fire](link_trait_1542) damage increases by 2d6, and the hazardous terrain [fire](link_trait_1542) damage increases by 2."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"pccdWdF0fwU3UKzZ","path":"packs/sf2e/spells/spells/rank-4/burstmoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"c8ce3fd92b4e95925b776a7beb6bf86c3a6afae9e7f90e0775486ce1ff6fcaff","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"150","url":"https://2e.aonsrd.com/spells/419-burstmoji"}},"content_source_id":900,"version":"1.0"},{"name":"Cable Management","rank":4,"uuid":345356194372513,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,2132],"defense":"Reflex","cost":"","trigger":null,"requirements":null,"range":"120 feet","area":"20-foot burst","targets":"","duration":"1 minute","description":"A massive tangle of interconnected computer cables springs forth from every direction at once. Spaces in the area become difficult terrain for the duration. Each time a creature begins a [move](link_trait_1505) action inside the tangle or enters the tangle during a [move](link_trait_1505) action, it must succeed at a Reflex save or take a –10-foot status penalty to its Speeds until it leaves the area. On a critical failure, the creature is also immobilized for 1 round. In addition, the cables are so thickly tangled that they provide standard cover to creatures in the area.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"nam1metCZqYItFck","path":"packs/sf2e/spells/spells/rank-4/cable-management.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"637d1eee3eb70bcd7ee2634f242d67c935164a8bd79fc348cd7001666870bd15","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"150","url":"https://2e.aonsrd.com/spells/420-cable-management"}},"content_source_id":900,"version":"1.0"},{"name":"Censormoji","rank":3,"uuid":4560471472847700,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"REACTION","traits":[1432,1433],"defense":"Will","cost":"","trigger":"A creature within range [Casts a Spell](link_action_19611) or performs an action with the [auditory](link_trait_1469) trait.","requirements":null,"range":"15 feet","area":null,"targets":"the triggering creature","duration":"","description":"You interrupt a creature's speech with a censoring emoji resembling a speaker with a line through it or a giant red X around its mouth or speakers. The triggering creature must attempt a Will save.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature is off-guard until the end of your next turn.\n\n**Failure** The creature is stupefied 1 and off-guard for 1 minute.\n\n**Critical Failure** The creature is stupefied 3 and off-guard for 1 minute.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"kmhaxRaiLMJM6DOg","path":"packs/sf2e/spells/spells/rank-3/censormoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"d6c507a8452b6fc8ef63ef9c19e3580c72749cd5e70432d9e8d8781759c1147d","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"150","url":"https://2e.aonsrd.com/spells/421-censormoji"}},"content_source_id":900,"version":"1.0"},{"name":"Circuit Trace","rank":2,"uuid":694535347719834,"traditions":["primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,2132],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"sustained up to 1 minute","description":"A tangle of golden and copper threads fills the space around you and trails behind you, making it difficult for others to pass. When you [Cast the Spell](link_action_19611) and the first time you [Sustain](link_action_19858) it on each subsequent round, you [Stride](link_action_19855) up to your Speed or 25 feet (whichever is lower), trailing wires behind you as the square you left becomes difficult terrain for the duration. You ignore difficult terrain created by _[circuit trace](link_spell_{{allocated:694535347719834}})_.","heightened":{"data":{},"text":[{"amount":"(5th)","text":"The spell creates greater difficult terrain."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"jqnRZasqIRUAP2Uy","path":"packs/sf2e/spells/spells/rank-2/circuit-trace.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"cd051fbe483f75f3f849d8a38ef604e15ba88fa91e80e3d818f1514e8dd43041","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"150","url":"https://2e.aonsrd.com/spells/422-circuit-trace"}},"content_source_id":900,"version":"1.0"},{"name":"Comfortmoji","rank":1,"uuid":7594714026965706,"traditions":["occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1442,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"1 creature","duration":"1 minute","description":"An emoji of a bandage covers the target, granting it fast healing 2 for the duration or until it removes the bandage, whichever comes first. The target or an ally (if the target is willing) can [Interact](link_action_19733) to remove the bandage and apply it to another adjacent creature, transferring the spell's benefits to the new creature. This does not reset the spell's duration.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The fast healing increases by 2."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"jChXPibVLmIC9QaE","path":"packs/sf2e/spells/spells/rank-1/comfortmoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"1e9fd75f597f300c069ea44a2398f2d66ee6414506a02a92ac82d18378a3b846","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"151","url":"https://2e.aonsrd.com/spells/423-comfortmoji"}},"content_source_id":900,"version":"1.0"},{"name":"Corrupt Machine","rank":2,"uuid":4088414473856312,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1846],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 [tech](link_trait_4506) weapon that’s unattended or wielded by a willing creature","duration":"1 minute","description":"You fuse an [unholy](link_trait_1846) spirit into the target, causing it to morph into a visibly horrifying version. The weapon gains the [unholy](link_trait_1846) trait and deals an additional 1d4 [fire](link_trait_1542) damage on hit. Creatures critically hit by this weapon also become frightened 1.","heightened":{"data":{},"text":[{"amount":"(4th)","text":"The damage increases to 2d4."},{"amount":"(6th)","text":"The damage increases to 3d4."},{"amount":"(8th)","text":"The damage increases to 4d4."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"iE2Zih3Uyq87oHjH","path":"packs/sf2e/spells/spells/rank-2/corrupt-machine.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"79fe55b423517bf172f2ce04733d9401aa9cda86ebd587a348a15113259da5c8","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"151","url":"https://2e.aonsrd.com/spells/425-corrupt-machine"}},"content_source_id":900,"version":"1.0"},{"name":"Cosmic Eddy","rank":5,"uuid":5930536301641312,"traditions":["divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1560,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"120 feet","area":"20-foot burst","targets":"","duration":"1 minute","description":"You conjure a swirling eddy of magical [force](link_trait_1560), battering your targets and hindering their movement. Creatures in the area when you [Cast the Spell](link_action_19611) or that start their turn there take 6d6 [force](link_trait_1560) damage with a basic Reflex save; on a failure, a creature also falls prone. The area is difficult terrain, and creatures attempting to [Fly](link_action_19721) in the area must attempt an Acrobatics check against your spell DC; on a failure, the movement is disrupted, and any remaining movement from the action is wasted. In addition, unattended items of light Bulk or less are thrown around within the eddy and land in a random space in the area when the spell ends.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 2d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"hY6HnTzr97uUqI2V","path":"packs/sf2e/spells/spells/rank-5/cosmic-eddy.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"d0f390e7654c5e697c9549756e0631d3f98d6ece43d8459d0fdeb06a1441679e","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"151","url":"https://2e.aonsrd.com/spells/426-cosmic-eddy"}},"content_source_id":900,"version":"1.0"},{"name":"Cosmic Radiation Rods","rank":4,"uuid":1010277874668965,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,2522],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":"10-foot emanation","targets":"","duration":"sustained up to 1 minute","description":"You summon forth an intangible field of thousands of tiny control rods to absorb ambient [radiation](link_trait_2522). These rods hover in the air all around you but are too small to affect sight lines or otherwise interfere with targeting. All allies within the area gain resistance 5 to damage from [radiation](link_trait_2522) effects and a +1 status bonus to Fortitude saves against [poison](link_trait_1476) and [radiation](link_trait_2522) effects.","heightened":{"data":{},"text":[{"amount":"(+3)","text":"The status bonus increases by 1, and the resistance increases by 5."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"hMYeUxTRfjSDhSRL","path":"packs/sf2e/spells/spells/rank-4/cosmic-radiation-rods.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"bc1c28e6336a58bd7ab7eae4d3923b7f450a3beb165a89fd482bf7e7a0ddc551","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"151","url":"https://2e.aonsrd.com/spells/427-cosmic-radiation-rods"}},"content_source_id":900,"version":"1.0"},{"name":"Crymoji","rank":1,"uuid":7646396499363138,"traditions":["arcane","divine","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1584],"defense":"Reflex","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":"10-foot burst","targets":"","duration":"sustained up to 1 minute","description":"You create an emoji that's crying so hard that it spreads water around itself, whether from laughter or sadness. When a creature starts to [Stride](link_action_19855) in the area the first time each turn, it must succeed at a Reflex saving throw or fall prone and take 1d6 bludgeoning damage, disrupting the movement. Each time you [Sustain](link_action_19858) the spell, the area increases by 5 feet.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"eChIzJ8Zvcmd6HWs","path":"packs/sf2e/spells/spells/rank-1/crymoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"fa2dc10e947d1de34b3d144f98f9076035e8c990608ef9b26d013743970eee54","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"151","url":"https://2e.aonsrd.com/spells/428-crymoji"}},"content_source_id":900,"version":"1.0"},{"name":"Dancemoji","rank":3,"uuid":6281101802857525,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"","duration":"sustained up to 1 minute","description":"You create a dancer emoji that inspires all that follow in its footsteps. When you [Cast the Spell](link_action_19611) and the first time you [Sustain](link_action_19858) it on each subsequent turn, the dancer emoji [Flies](link_action_19721) or [Strides](link_action_19855) up to 20 feet, leaving a trail of glowing dance floor in each space it travels through that lingers for the duration. Allies who enter the trail or start their turn there gain a +5-foot status bonus to their Speeds until the end of the turn. An ally who starts to [Fly](link_action_19721) or [Stride](link_action_19855) on the trail and doesn't leave it for the entire movement also gains a +1 circumstance bonus to their AC until the start of their next turn, mimicking the dancer's graceful movements.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"e98MfMLWgbwOFCZo","path":"packs/sf2e/spells/spells/rank-3/dancemoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"c7f808761c00d2d9c778045d2034711aaa0c86f9efbcfe290e598ca81e4f6370","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"151","url":"https://2e.aonsrd.com/spells/429-dancemoji"}},"content_source_id":900,"version":"1.0"},{"name":"Divine Firewall","rank":8,"uuid":4638504340977413,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1630,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":"60-foot emanation","targets":"","duration":"1 minute","description":"You fill the space around you with divine flames that protect allies within it and burn away those who mean you harm, especially from [unholy](link_trait_1846) and technological threats. You and allies in the area are concealed. As the nature of this effect still leaves the target's location obvious, the target can't use this concealment to [Hide](link_action_19726) or [Sneak](link_action_19850).\n\nEnemies beginning their turn in the area take 10 [fire](link_trait_1542) damage, become glitching 1 if they have the [tech](link_trait_4506) trait, and become off-guard for 1 round if they have the [unholy](link_trait_1846) trait.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"WzROOMfaK77OMgjB","path":"packs/sf2e/spells/spells/rank-8/divine-firewall.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"91c532d26c76cc157f8e0a638cbb8bfdc6c1de32e911ed2a55607712cefb6716","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"152","url":"https://2e.aonsrd.com/spells/430-divine-firewall"}},"content_source_id":900,"version":"1.0"},{"name":"Divine Machine","rank":5,"uuid":3718062735752641,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1453],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 ally with the [tech](link_trait_4506) trait","duration":"1 minute","description":"You surround your target with shimmering divine magic that coalesces into technological armor, building them a large, resilient shell. For the duration of the spell, the target stands taller, functions more reliably, and gains supernatural protection from harm. The target grows to Large size unless it's already Large or larger. Its equipment grows with it but returns to its usual size if removed. Its reach increases by 5 feet (or by 10 feet if it started out Tiny). The target also gains a +2 status bonus to AC and saving throws and 20 temporary Hit Points for the duration. The spell ends immediately when the target has no temporary Hit Points.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The temporary Hit Points granted by this spell increase by 5."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"TW5UKhYiXlT66Ivu","path":"packs/sf2e/spells/spells/rank-5/divine-machine.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"5ef0d0369944620bf455adaec7e1fe970d74425541daf69ad9a5e2f173981716","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"152","url":"https://2e.aonsrd.com/spells/431-divine-machine"}},"content_source_id":900,"version":"1.0"},{"name":"Emoji Armament","rank":3,"uuid":8929721471337370,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1560,1433],"defense":"AC","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"1 creature","duration":"1 minute","description":"You conjure an emoji of a weapon. Attempt a spell attack roll against a target's AC within 60 feet of the emoji (or adjacent if the emoji is a melee weapon), dealing 4d6 [force](link_trait_1560) damage on a hit (double damage on a critical hit). You can repeat the attack as a reaction when a creature in range uses a [manipulate](link_trait_1433) action (or [move](link_trait_1505) action, if the emoji is a melee weapon), but the spell ends at the start of your turn if you haven't used this reaction since the end of your previous turn. You can move the emoji each time you [Sustain](link_action_19858) the Spell.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"QnVLetx8Ajiu5XVk","path":"packs/sf2e/spells/spells/rank-3/emoji-armament.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"be2a5f754434387ec847ebfe7ffb4114b3c8eef0285e9e6c6e8461b84f57f3bf","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"152","url":"https://2e.aonsrd.com/spells/432-emoji-armament"}},"content_source_id":900,"version":"1.0"},{"name":"Emoji Shield","rank":2,"uuid":496096198301308,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":"Fortitude","cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"1 minute or until dismissed","description":"You create a shield emoji that protects you from harm and explodes in a burst of blinding light when it's broken into magical code. You gain a +1 status bonus to AC and the Emoji Burst reaction.\n\n**Emoji Burst** <abbr cost=\"REACTION\" class=\"action-symbol\">R</abbr> ([light](link_trait_1517), [visual](link_trait_1479)) **Trigger** A creature hits you with a [Strike](link_action_19856); **Effect** You pop the emoji, creating a bright light in a 5-foot emanation. Creatures in the area must succeed at a Fortitude save or become dazzled until the end of your next turn (blinded on a critical failure).","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"ONyatkj2Ds1laXLO","path":"packs/sf2e/spells/spells/rank-2/emoji-shield.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"9411de4c625f6a27728bd9b863475a2dc7d2483f9d9b5113aa6be5de0b5cc6f2","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"152","url":"https://2e.aonsrd.com/spells/433-emoji-shield"}},"content_source_id":900,"version":"1.0"},{"name":"Emoji Spam","rank":4,"uuid":7277275666557824,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1448,1479],"defense":"Will","cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 creature","duration":"","description":"You overwhelm a creature's senses with a barrage of different emojis, each eliciting a different sensation, memory, or otherwise deeply rooted connection that causes their brain to overload with information. The creature takes 6d6 [mental](link_trait_1448) damage and must attempt a Will save.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature takes half damage and is dazzled until the start of your next turn.\n\n**Failure** The creature takes full damage plus an additional 1d6 persistent [mental](link_trait_1448) damage. While taking this persistent damage, the creature is dazzled and can only speak in emojis. While speaking in only emojis, the creature can't cast spells or use [auditory](link_trait_1469) and [sonic](link_trait_1484) effects, except those that have \"emoji\" or \"moji\" in their name or the [subtle](link_trait_1899) trait. The creature can still communicate by speaking, but doing so loses the [auditory](link_trait_1469) trait and gains the [visual](link_trait_1479) trait.\n\n**Critical Failure** As failure, but the creature takes double damage, and the creature is blinded while taking the persistent damage. When it loses the persistent damage, it becomes dazzled until the end of its next turn.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The [mental](link_trait_1448) damage increases by 2d6, and the persistent [mental](link_trait_1448) damage increases by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"J0uCmkZq1uLAun94","path":"packs/sf2e/spells/spells/rank-4/emoji-spam.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"6b82c934e34f383a1b3917102372d6020cec11d417ec3271d5752d16e43dd008","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"152","url":"https://2e.aonsrd.com/spells/434-emoji-spam"}},"content_source_id":900,"version":"1.0"},{"name":"Emoji Spray","rank":1,"uuid":3373659099376032,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":"varies","cost":"","trigger":null,"requirements":null,"range":"","area":"15-foot cone","targets":"","duration":"","description":"You unleash a cone of thematic emojis. Choose a type of emoji you spray, which determines the effects of the spell. Each creature in the area experiences the chosen effect. \n\n- **Eye Emojis** Bright eyes cling to the creature, which must attempt a Fortitude save. _[emoji spray](link_spell_{{allocated:3373659099376032}})_ gains the [light](link_trait_1517) and [visual](link_trait_1479) traits.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature is distracted by the light, becoming off-guard until the start of your next turn.\n\n**Failure** As success, but the creature can't benefit from the concealed condition and takes a –2 circumstance penalty to Stealth checks to [Hide](link_action_19726) for as long as it's off-guard.\n\n- **Food Emojis** Food gets into the creature's circuits. The creature must succeed at a Reflex save or the creature and one [tech](link_trait_4506) item of your choice that it's holding becomes glitching 1 (glitching 2 on a critical failure).\n\n- **Grawlix Emojis** Symbols representing profanity barrage the creature, dealing 2d4 [mental](link_trait_1448) damage (basic Will save); on a failure, it also becomes stupefied 1 (stupefied 3 on a critical failure). _[emoji spray](link_spell_{{allocated:3373659099376032}})_ gains the [mental](link_trait_1448) trait.\n\n- **Weapon Emojis** Swords and daggers pierce the creature, dealing 1d6 persistent bleed damage (basic Reflex save) as the weapons tear into it.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The [mental](link_trait_1448) damage increases by 2d4, and the persistent bleed damage increases by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"HmiwNtwDnfRKGrSI","path":"packs/sf2e/spells/spells/rank-1/emoji-spray.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"e5a2f8ee55a251462f8a550925a4e4030df2fec79ad717ed82a0d903a3670625","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/435-emoji-spray"}},"content_source_id":900,"version":"1.0"},{"name":"Emoji Tsunami","rank":7,"uuid":6203298667043597,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1560,1433,1584],"defense":"Reflex","cost":"","trigger":null,"requirements":null,"range":"","area":"60-foot cone","targets":"","duration":"","description":"You unleash a wave of emojis. Creatures in the area take 13d6 bludgeoning damage and must attempt a Reflex saving throw.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature takes half damage and is pushed 10 feet away from you. This is forced movement.\n\n**Failure** As success, but the creature takes full damage and is also knocked prone.\n\n**Critical Failure** As failure, but the creature takes double damage and is also blinded for 1 minute by lingering water droplet emojis.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 2d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"EsmK1lCqW9wjGXHh","path":"packs/sf2e/spells/spells/rank-7/emoji-tsunami.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"730750c4b87155c4e9b878dcd55fa30d0d4f45292bccca75bfa7ca4f15a22371","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/436-emoji-tsunami"}},"content_source_id":900,"version":"1.0"},{"name":"Exhale Toxins","rank":1,"uuid":6961811307717529,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1476],"defense":"Fortitude","cost":"","trigger":null,"requirements":"You have a [filtered rebreather](link_item_19837) or other air filter, used as a locus.","range":"","area":"15-foot cone","targets":"","duration":"","description":"You release all the built-up toxins in the locus at once, exhaling a poisonous mist. Creatures in the area take 2d4 [poison](link_trait_1476) damage and must attempt a Fortitude save.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature takes half damage.\n\n**Failure** The creature takes full damage and is sickened 1.\n\n**Critical Failure** The creature takes double damage and is sickened 2.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 2d4."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"9jZ8lah3VMO7iYW8","path":"packs/sf2e/spells/spells/rank-1/exhale-toxins.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"86cdc30e8540ba740e15f8be36452561a504e3c7827127350ae971e40a339448","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/438-exhale-toxins"}},"content_source_id":900,"version":"1.0"},{"name":"Explosive Recall","rank":6,"uuid":3076881430119778,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":"You have a functional grenade, used as a locus.","range":"","area":null,"targets":"","duration":"1 minute","description":"You capture and repeat the memory of a grenade's explosion within its shell. If you [Area-Fire](link_action_44905) with the locus during the duration of the spell, the grenade's effect is repeated in the same area 1 round after the initial activation.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"7o0Fbp7CsocbKSab","path":"packs/sf2e/spells/spells/rank-6/explosive-recall.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"de1d5ee67769039f89f82de93e28e469ed4a0b761d7436713c8094c55461e25f","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/439-explosive-recall"}},"content_source_id":900,"version":"1.0"},{"name":"Flight of the Lightning Bees","rank":8,"uuid":1987099207117874,"traditions":["occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1576,1433],"defense":"Fortitude","cost":"","trigger":null,"requirements":null,"range":"120 feet","area":"up to 4 non-overlapping 20-foot bursts","targets":"","duration":"1 minute","description":"Beelike elementals made of pure [electricity](link_trait_1576) swarm out of countless portals. When you [Cast the Spell](link_action_19611) and the first time you [Sustain](link_action_19858) the spell each subsequent round, creatures in the area take 6d12 piercing damage and 3d6 persistent [electricity](link_trait_1576) damage and must attempt a Fortitude save. The first time you [Sustain](link_action_19858) the spell each subsequent round, you can also move one of the bursts 15 feet in any direction, though you can't move bursts so they overlap.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature takes half damage and is suppressed for 1 round.\n\n**Failure** The creature takes full damage and is suppressed for as long as it takes the persistent damage.\n\n**Critical Failure** The creature takes double damage and is suppressed and clumsy 2 for as long as it takes the persistent damage.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The piercing damage increases by 1d12."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"6IAcZLBCv4SECaFU","path":"packs/sf2e/spells/spells/rank-8/flight-of-the-lightning-bees.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"3bff4355465002a038cca233d4cabb0fc0abdb3ef0b6477b6936b19c7695ef47","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/440-flight-of-the-lightning-bees"}},"content_source_id":900,"version":"1.0"},{"name":"Ghostmoji","rank":4,"uuid":3536434187342192,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1486,1487,1481,1433,1448],"defense":"Will","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"1 creature","duration":"","description":"You create a terrifying ghost emoji that only the target can see. The target must attempt a Will save.\n\n**Critical Success** The target is unaffected.\n\n**Success** The target is frightened 1.\n\n**Failure** The target is frightened 2 and stunned 2.\n\n**Critical Failure** The target is frightened 3 and fleeing, and it's slowed 2 for as long as it remains frightened.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"5ndwZJL0Olg9gohU","path":"packs/sf2e/spells/spells/rank-4/ghostmoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"535f3326e28ba1c864e20cba96b59d709bfecfd4a2195b6696c91b61af658ee6","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"153","url":"https://2e.aonsrd.com/spells/441-ghostmoji"}},"content_source_id":900,"version":"1.0"},{"name":"Holographic Stand-In","rank":4,"uuid":2108284513759850,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"120 feet","area":null,"targets":"","duration":"sustained up to 1 minute","description":"You create a convincing holographic copy of yourself. This hologram looks exactly like you, but it's incorporeal and mimics your movements. When you [Sustain](link_action_19858) the spell, you can Command the hologram to act differently. Characters can discern the nature of the hologram with a Perception check, or by interacting with it in any way, such as attempting to [Strike](link_action_19856) it. You can look through the hologram's eyes by closing your own as part of a [Seek](link_action_19845) action. The spell immediately ends if you lose line of effect to your hologram.","heightened":{"data":{},"text":[{"amount":"(9th)","text":"The maximum duration you can [Sustain](link_action_19858) the spell increases to 10 minutes."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"4yllv8kIihHNb2xj","path":"packs/sf2e/spells/spells/rank-4/holographic-stand-in.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"e373cefd5a45dfb74198ffda649842152788be3ff34b994e1f6200f370b976c8","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"154","url":"https://2e.aonsrd.com/spells/442-holographic-stand-in"}},"content_source_id":900,"version":"1.0"},{"name":"Hot Swap","rank":3,"uuid":2057495414296206,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1433,1470],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"touch","area":null,"targets":"2 unattended weapons","duration":"1 hour","description":"You create a mystical bond between the targets, allowing them to switch positions. For the duration, creatures wielding either weapon gain the Swap action.\n\n**Swap** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> ([concentrate](link_trait_1432), [teleportation](link_trait_1470)) **Requirements** A creature is wielding the other weapon and is within 100 feet of you; **Effect** You instantly swap the location of the targeted weapons. If the remaining duration of _[hot swap](link_spell_{{allocated:2057495414296206}})_ is more than 10 minutes, reduce its remaining duration to 10 minutes.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"32rKBaTBCJ33qixz","path":"packs/sf2e/spells/spells/rank-3/hot-swap.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"24a2864d7ecb37c07ba4eb497b5bfd049937bcb77c221ee5a19f181d643d6632","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"154","url":"https://2e.aonsrd.com/spells/443-hot-swap"}},"content_source_id":900,"version":"1.0"},{"name":"Infectious Virus","rank":4,"uuid":1553080120555270,"traditions":["occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1576,1433],"defense":"Fortitude","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":"20-foot burst","targets":"","duration":"","description":"You craft a dangerous computer virus. All creatures with the [tech](link_trait_4506) trait in the area take 10 persistent [electricity](link_trait_1576) damage and must attempt a Fortitude save.\n\n**Critical Success** The target is unaffected.\n\n**Success** The target takes half damage and is glitching 1.\n\n**Failure** The target takes full damage and is glitching 2.\n\n**Critical Failure** The target takes double damage and is glitching 4.","heightened":{"data":{},"text":[{"amount":"(+2)","text":"The persistent damage increases by 5."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"2Ln6XZujQYZK95Mv","path":"packs/sf2e/spells/spells/rank-4/infectious-virus.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"2f600cccef9e1985bd06b138be877b671a1a1c8a6a4b96d79348dbfc4d6e9583","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"154","url":"https://2e.aonsrd.com/spells/444-infectious-virus"}},"content_source_id":900,"version":"1.0"},{"name":"Infuse Ammo","rank":3,"uuid":8691667952110702,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"ONE-ACTION","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":"You're wielding a projectile weapon.","range":"","area":null,"targets":"","duration":"","description":"You enhance your next round of ammunition with the might of the elements, empowering the next round in the chamber. When you [Cast this Spell](link_action_19611), choose an [elemental](link_trait_2406) trait and corresponding type of damage: [electricity](link_trait_1576) or [sonic](link_trait_1484) for [air](link_trait_1524), bludgeoning or piercing for [earth](link_trait_1523), [acid](link_trait_1528) or slashing for [metal](link_trait_2132), [fire](link_trait_1542) for [fire](link_trait_1542), bludgeoning or [cold](link_trait_1519) for [water](link_trait_1584), or piercing or [poison](link_trait_1476) for [wood](link_trait_1680). The next [Strike](link_action_19856) you make with the wielded weapon before the end of your next turn gains the chosen [elemental](link_trait_2406) trait, damage trait, and deals an additional 1d6 damage of the chosen type of damage.","heightened":{"data":{},"text":[{"amount":"(6th)","text":"The additional damage increases to 2d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"0Ut3WWGJP2dpjSwY","path":"packs/sf2e/spells/spells/rank-3/infuse-ammo.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"584285d788a4a5899de3d67d47d6fbded48f1caf9b16fd149272dab0457a2e20","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"154","url":"https://2e.aonsrd.com/spells/445-infuse-ammo"}},"content_source_id":900,"version":"1.0"},{"name":"Instant Messaging","rank":3,"uuid":910297482701427,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1458,1433,1448,1479],"defense":null,"cost":"","trigger":null,"requirements":"You have a [comm unit](link_item_18663) or other long-range communications device, used as a locus.","range":"","area":null,"targets":"","duration":"10 minutes","description":"You use your [comm unit](link_item_18663) as a focus for communication, projecting messages to those nearby. You can communicate telepathically with creatures within 30 feet by using a free hand to type a message into your [comm unit](link_item_18663) or whispering into the mic. This communication is one-way, and you can only communicate with creatures that share a language with you. You can choose which creatures receive your communications, and those creatures know you were the one who transmitted the message.","heightened":{"data":{},"text":[{"amount":"(5th)","text":"You can communicate with images rather than words. _[instant messaging](link_spell_{{allocated:910297482701427}})_ loses the [linguistic](link_trait_1458) trait."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"0P9ragdbl7dIH7aH","path":"packs/sf2e/spells/spells/rank-3/instant-messaging.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"3103a2b1f801d4047da0b8955b68394a5b3b5b06115b4aed7115de60039c7dcc","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"155","url":"https://2e.aonsrd.com/spells/446-instant-messaging"}},"content_source_id":900,"version":"1.0"},{"name":"Judgment Cannon","rank":7,"uuid":52679978291994,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1433,1897,1556],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"","duration":"sustained up to 1 minute","description":"You create a ghostly, semi-corporeal turret made of divine force in an unoccupied space in range. The turret is Medium; creatures can move through the turret's space but can't end their movement in it. When you [Cast the Spell](link_action_19611) and the first time you [Sustain](link_action_19858) it each turn on subsequent rounds, the turret fires, dealing 8d8 [spirit](link_trait_1556) damage to all creatures in a 60-foot line originating from the turret (basic Reflex save).","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 1d8."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"onJigrID4TH48kag","path":"packs/sf2e/spells/spells/rank-7/judgment-cannon.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"1e5a9014aca85ee5688cafaea106e57e82146cc36e8574203ccde5b1ff4ecaf1","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"155","url":"https://2e.aonsrd.com/spells/447-judgment-cannon"}},"content_source_id":900,"version":"1.0"},{"name":"Junk Form","rank":6,"uuid":4660643601846186,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433,1453],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"1 minute","description":"You transform your body into a Large battle form made of junk. When you [Cast this Spell](link_action_19611), choose e-waste, filth, or scrap. While in this form, you gain the [tech](link_trait_4506) trait. You can [Dismiss](link_action_19627) the spell.\n\nYou gain the following statistics and abilities regardless of which option you choose: \n\n- AC = 17 + your level. Ignore your armor's check penalty and Speed reduction, but you can still use any armor upgrades or environmental protections you have. \n\n- [Darkvision](link_sense_20769).\n\n- One or more unarmed attacks specific to the battle form you choose, which are the only attacks you can [Strike](link_action_19856) with. You're trained with them. Your attack modifier is +22, and your damage bonus is +6. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n\nYou also gain abilities based on the battle form you choose:\n\n- **E-Waste** Speed 25 feet (hover), fly 20 feet; **Weaknesses** bludgeoning 5; **Resistances** [electricity](link_trait_1576) 10; **Static Feedback** ([electricity](link_trait_1576)) A creature that hits you with a melee [Strike](link_action_19856) takes 1d4 [electricity](link_trait_1576) damage. If the weapon has the [tech](link_trait_4506) trait, they must succeed at a Reflex save against your spell DC or the weapon becomes glitching 1; **Melee** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> fan blade, **Damage** 2d6 slashing plus 2d6 [electricity](link_trait_1576); **Ranged** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> power surge (range 60 feet), **Damage** 2d4 [electricity](link_trait_1576) plus 2d4 [fire](link_trait_1542).\n- **Filth** Speed 20 feet; **Weaknesses** slashing 5; **Resistances** [poison](link_trait_1476) 10; **Rancid Stench** ([aura](link_trait_1492), [olfactory](link_trait_2131), [poison](link_trait_1476)) 10 feet. A creature that enters or starts their turn in the [aura](link_trait_1492) must succeed at a Fortitude save against your spell DC or become sickened 1 (sickened 2 on a critical failure). Creatures can't retch to reduce their sickened value within the [aura](link_trait_1492). If a creature succeeds, or once they recover from this sickened condition, it's temporarily immune to the [aura](link_trait_1492) for 24 hours; **Melee** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> sludge slug, **Damage** 2d8 bludgeoning plus 1d6 persistent [poison](link_trait_1476); **Ranged** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> garbage dump (range 20 feet), **Damage** 2d6 bludgeoning plus 1d6 persistent [poison](link_trait_1476).\n- **Scrap** Speed 20 feet, climb 20 feet; **Weaknesses** [electricity](link_trait_1576) 5; **Resistances** slashing 10; **Melee** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> scrap slug, **Damage** 2d8 bludgeoning plus 2d8 slashing; **Ranged** <abbr cost=\"ONE-ACTION\" class=\"action-symbol\">1</abbr> scrap shot (range 60 feet), **Damage** 3d8 bludgeoning","heightened":{"data":{},"text":[{"amount":"(8th)","text":"Your battle form is Huge, you gain a +15-foot status bonus to your Speeds, and your melee attacks have 10-foot reach. You instead gain AC = 21 + your level, 15 temporary Hit Points, an attack modifier of +28, and a damage bonus of +12. Static feedback deals 2d4 [electricity](link_trait_1576) damage."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"155","url":"https://2e.aonsrd.com/spells/449-junk-form"}},"content_source_id":900,"version":"1.0"},{"name":"Junkify","rank":1,"uuid":7748968230499214,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"touch","area":null,"targets":"1 [construct](link_trait_2410), item, or object that’s made of metal or that has the [tech](link_trait_4506) trait","duration":"","description":"You corrode a useful piece of [tech](link_trait_4506) into obsolete junk. The target takes 1d8 [acid](link_trait_1528) damage, with a basic Reflex save if the target is a creature or by a creature holding or wielding the target. The target becomes glitching 2 on a failure (or if unattended). If this damage reduces the target to 0 Hit Points, it becomes junk, and as long as it's unattended, any space it occupies becomes difficult terrain.","heightened":{"data":{},"text":[{"amount":"(+2)","text":"Increase the damage by 1d8 and the glitching condition by 1."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"WYzRscCSsB8wT6Aq","path":"packs/sf2e/spells/spells/rank-1/junkify.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"5fc72a7ab8c9624101fb22dc83bb852c283958cb77698b70c437ca24c48d1349","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"156","url":"https://2e.aonsrd.com/spells/454-junkify"}},"content_source_id":900,"version":"1.0"},{"name":"Kill Dash Nine","rank":9,"uuid":8461582912808814,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":"Will","cost":"","trigger":null,"requirements":null,"range":"120 feet","area":null,"targets":"1 creature with the [tech](link_trait_4506) trait","duration":"","description":"You send a brutal signal interruption straight into the central processor of a technological being. This signal wreaks havoc on the system and leaves behind lasting corruption. The target takes 15d8 [mental](link_trait_1448) damage, or [electricity](link_trait_1576) damage, if the target is immune to [mental](link_trait_1448) damage. Beings that are biomechanical (such as androids) or only partially mechanical (such as cyborgs) uses the outcome for one degree of success better than the result of their saving throw.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature takes half damage and becomes glitching 1.\n\n**Failure** The creature takes full damage and becomes glitching 2 and stunned 1.\n\n**Critical Failure** The creature takes double damage, becomes glitching 3 and stunned 2, and must succeed at a Fortitude save or suffer catastrophic systems failure. This kills any creature reliant on technology to live. This Fortitude save has the [death](link_trait_1904) and [incapacitation](link_trait_1481) traits.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"SrgvGhssLCzzhiNo","path":"packs/sf2e/spells/spells/rank-9/kill-dash-nine.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"c66649fe6605d2772248fb3aa7252c688806539b143ddcc2f3a3b0c5aed398c8","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"156","url":"https://2e.aonsrd.com/spells/455-kill-dash-nine"}},"content_source_id":900,"version":"1.0"},{"name":"Light Shift","rank":4,"uuid":2705096733488798,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1517,1433,1470],"defense":null,"cost":"","trigger":null,"requirements":"You have a [laser pistol](link_item_19684), [laser rifle](link_item_19694), or other device capable of producing a laser, used as a locus.","range":"","area":null,"targets":"","duration":"","description":"You fire the locus and instantly transfer yourself along the beam, transforming you and your equipment into photons for a fraction of a second. You teleport to an occupied space within the first range increment of the locus, and you shed bright light in a radius equal to the distance you teleported that lasts until the end of your turn.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"Py97Kb5H6vrgELDa","path":"packs/sf2e/spells/spells/rank-4/light-shift.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"60ad8c2eb8e1e0175f9dfb9aaecaa48ec15fc97cf95c71907084901618bab3ca","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/456-light-shift"}},"content_source_id":900,"version":"1.0"},{"name":"Mycorrhizal Supremacy","rank":9,"uuid":1027776995501182,"traditions":["primal"],"rarity":"UNCOMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1481,1433,1448,2938],"defense":"Will","cost":"","trigger":null,"requirements":null,"range":"120 feet","area":null,"targets":"1 living creature (see text below)","duration":"until your next daily preparations","description":"You create a network of mind-controlling mycotoxins directly in targets' brains, attempting to seize command and force them to obey you. The first target must attempt a Will save. If it doesn't critically succeed, another target within 30 feet of the first attempts a Will save; if that target doesn't critically succeed, another target within 30 feet of it attempts a Will save, and so on. You can choose to end the spread at any point, and you can't target the same creature more than once. Once the spell has taken effect, you can only focus on one member of the network to control at a time. You can change the target of your focus by [Sustaining](link_action_19858) the spell.\n\n**Critical Success** The target is unaffected, and your network can spread no farther.\n\n**Success** The target is stunned 1 as it fights off your spores.\n\n**Failure** The target joins your mycorrhizal network. It gains the controlled condition but can act normally unless it's the focus of your control. If it's the focus, it can attempt a Will save at the end of each of its turns. On a success, the target drops out of the network, and your focus automatically shifts to the closest remaining member of the network.\n\n**Critical Failure** As a failure, but the target receives a new save only if you give it a new order that's against its nature, such as killing its allies.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"LcAzycyG5Tqk92Bx","path":"packs/sf2e/spells/spells/rank-9/mycorrhizal-supremacy.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"d05746908bfadfdc7b5da45d963944af9ec996488e65e1828c67304fca0d616f","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/458-mycorrhizal-supremacy"}},"content_source_id":900,"version":"1.0"},{"name":"Nanite Snipe","rank":1,"uuid":6584059860247452,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":"AC","cost":"","trigger":null,"requirements":null,"range":"30 to 120 feet","area":null,"targets":"1 creature","duration":"","description":"Make a spell attack roll against the target's AC, dealing 1d12 piercing damage on a hit with a [tech](link_trait_4506) target becomes glitching 2. On a critical hit, the target takes double damage, and a [tech](link_trait_4506) target becomes glitching 4.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 1d12."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"IKoJFpftmymU0JxI","path":"packs/sf2e/spells/spells/rank-1/nanite-snipe.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"fba0fb2a011a2eec432a8ba459f0776f987a71ca47b55298e407b760097b0e57","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/459-nanite-snipe"}},"content_source_id":900,"version":"1.0"},{"name":"One with Junk","rank":3,"uuid":4268785368499029,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433,1453],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"10 minutes or 8 hours","description":"You can either transform into junk or merge with it. This spell has the same effects as _[one with plants](link_spell_4746)_ but lets you merge with or turn into a pile of junk or a larger piece of junk, such as trash bags, a heap of scrap metal, or a broken construct. Junk you turn into has AC 23. You can [Dismiss](link_action_19627) this spell.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"HT4nqVPlQKKi2jdV","path":"packs/sf2e/spells/spells/rank-3/one-with-junk.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"9a927d20a4ab61d38763927487b1342d0b9ad175a8acbade5ee22c019261097d","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/460-one-with-junk"}},"content_source_id":900,"version":"1.0"},{"name":"Optic Blast","rank":2,"uuid":1085870518543655,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1560,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":"You have protective eyewear, used as a locus.","range":"","area":"30-foot line","targets":"","duration":"","description":"Your eyes boil with magical energy, building up pressure behind the locus until it bursts forth. Creatures in the area take 3d6 [force](link_trait_1560) damage with a basic Reflex save. Creatures that fail their save are also knocked back 5 feet.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 2d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"H1DWnlnm2DupjAep","path":"packs/sf2e/spells/spells/rank-2/optic-blast.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"4e688c79d01aa027ad03e3b1f5559bf8b87178abcb4f7804ddd0c704bec74c2d","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/461-optic-blast"}},"content_source_id":900,"version":"1.0"},{"name":"Optics Feed","rank":1,"uuid":6201299563347772,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1590],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"touch","area":null,"targets":"1 willing creature with the [tech](link_trait_4506) trait or a visual augmentation","duration":"10 minutes","description":"You tap into the optical scanners of a machine and turn it into a live camera feed. For the spell's duration, you can stream what the target sees via any screen you touch.","heightened":{"data":{},"text":[{"amount":"(3rd)","text":"The spell's duration is 1 hour."},{"amount":"(6th)","text":"The spell's duration is 1 day."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"FhcGSV1rbFWHiXJD","path":"packs/sf2e/spells/spells/rank-1/optics-feed.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"05b01b33ac25975226651a4b9fce68474cd197a89e2bc76701e96224e16a2b3a","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"157","url":"https://2e.aonsrd.com/spells/462-optics-feed"}},"content_source_id":900,"version":"1.0"},{"name":"Paywall","rank":5,"uuid":3343527481635184,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"","duration":"1 minute","description":"You form a transparent wall of hardlight featuring payment terms in many languages. Each 10-foot-by-10-foot section of the wall has AC 10, Hardness 18, and 60 Hit Points, and its immune to critical hits and precision damage. The wall can be passed through by paying 10 credits and verifying the transaction as an single action with the [auditory](link_trait_1469) trait. Creatures that carry a credstick can pass, even if its empty, though in this case they pass through by taking on 10 credits of debt.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The Hit Points of each section of the wall increase by 15."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"CsLA3rJ9pwHb2loe","path":"packs/sf2e/spells/spells/rank-5/paywall.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"115cae242a34f00609355ea65d2e3b7c2e51b6db62ad0226a617b5d8e181caa0","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"158","url":"https://2e.aonsrd.com/spells/463-paywall"}},"content_source_id":900,"version":"1.0"},{"name":"Positronic Helmet","rank":3,"uuid":1918195228946537,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1448,1456],"defense":"basic Will","cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"1 minute","description":"A magical robotic headpiece builds out from you, transforming your brain into a central processing unit and bolstering your mind. You gain the [tech](link_trait_4506) trait for the duration of the spell. You gain a +1 status bonus to Perception checks and Will saves. You can [Sustain](link_action_19858) this spell once per turn to fire a [mental](link_trait_1448) beam from the helmet that deals 2d10 [mental](link_trait_1448) damage to creatures in a 30-foot line with a basic Will save.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 1d10."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"AZUxwGaKz3qTCMvk","path":"packs/sf2e/spells/spells/rank-3/positronic-helmet.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"df39dc0a7a99b325841057c6f72f31a5903db49fa2c1481fb9db4e2eb3a86fcf","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"158","url":"https://2e.aonsrd.com/spells/464-positronic-helmet"}},"content_source_id":900,"version":"1.0"},{"name":"Prayermoji","rank":5,"uuid":5578204997222495,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1897,1556],"defense":"basic Fortitude","cost":"","trigger":null,"requirements":"You worship a deity.","range":"","area":null,"targets":"","duration":"sustained up to 1 minute","description":"You project an emoji of your deity's religious symbol around yourself. When you [Cast the Spell](link_action_19611) and the first time you [Sustain](link_action_19858) it on each subsequent turn, choose one of the following benefits depending on the emoji used.\n\n- **Prayer of Grace** You gain a +20-foot status bonus to your Speeds until the start of your next turn.\n- **Prayer of Healing** You regain 4 Hit Points at the start of your next turn.\n- **Prayer of Protection** You gain a +1 status bonus to AC and saving throws until the start of your next turn.\n- **Prayer of Retribution** Until the start of your next turn, creatures that hit you with melee [Strikes](link_action_19856) take 4 [spirit](link_trait_1556) damage.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The Hit Points regained increase by 1, and the [spirit](link_trait_1556) damage increases by 1."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"7nzp5SwP5NoS3RRt","path":"packs/sf2e/spells/spells/rank-5/prayermoji.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"4b5aaad4785cb39903f0cb4b0dc108979b8151733e27543b8438d89a002f65e5","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"158","url":"https://2e.aonsrd.com/spells/465-prayermoji"}},"content_source_id":900,"version":"1.0"},{"name":"Read Memory","rank":1,"uuid":4139380956698506,"traditions":["arcane","divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"touch","area":null,"targets":"1 functional [comm unit](link_item_18663) or computer you can access","duration":"","description":"You touch a computer screen, learning what it has recently displayed, even if it's been rebooted or used for something else since then. You choose one of the following pieces of information, and the computer truthfully displays or plays it. \n\n- The last command entered into the target.\n\n- The name of the last file accessed on the target.\n\n- The name of the last file downloaded to or uploaded from the target.\n\n- The last 1 minute of audio played from the target.","heightened":{"data":{},"text":[{"amount":"(3rd)","text":"Choose two of the options."},{"amount":"(5th)","text":"Choose all of the options."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"5ZG4T2nGy1g2RJvA","path":"packs/sf2e/spells/spells/rank-1/read-memory.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"765d05d8d6820671fced2616d91a9cfda0e2320f030897a98bd247d890801ac0","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"158","url":"https://2e.aonsrd.com/spells/466-read-memory"}},"content_source_id":900,"version":"1.0"},{"name":"Reflective Paneling","rank":5,"uuid":5865474209416714,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":"You're wearing armor with the [tech](link_trait_4506) trait, used as a locus.","range":"","area":null,"targets":"","duration":"1 minute","description":"The plates of your armor harden and become more reflective, enhanced with defensive magic. When you [Cast this Spell](link_action_19611), choose [electricity](link_trait_1576), [fire](link_trait_1542), piercing, or slashing damage. For the duration, you gain resistance 10 to that damage type and gain the Reflect Damage reaction.\n\n**Reflect Damage** <abbr cost=\"REACTION\" class=\"action-symbol\">R</abbr> **Trigger** You take damage of the chosen type; **Effect** Your armor's plates harden further, reflecting the damage. Make a spell attack roll against the creature that dealt the triggering damage.\n\n**Critical Success** The creature takes double the triggering damage or double your resistant to the triggering damage, which ever is lower.\n\n**Success** As critical success, but the damage is not doubled.\n\n**Failure** The spell ends.","heightened":{"data":{},"text":[{"amount":"(8th)","text":"You can choose two damage types, and the resistance increases to 15. You can only Reflect Damage of one type at a time."},{"amount":"(10th)","text":"As 8th, except the spell protects you against all four damage types, and the resistance increases to 20."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"3iJb9h4yRGyIRzJd","path":"packs/sf2e/spells/spells/rank-5/reflective-paneling.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"81fa71602a92c19094eac5d7ea9f96fb728ccb80adeabd9f9883a1ab44222582","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"158","url":"https://2e.aonsrd.com/spells/467-reflective-paneling"}},"content_source_id":900,"version":"1.0"},{"name":"Reparative Nanites","rank":1,"uuid":933894963613079,"traditions":["divine","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1442,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 creature","duration":"1 minute","description":"You conjure a cloud of nanites that repair the target on a molecular level. The target gains fast healing 1.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The fast healing increases by 1."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"327oTvddhYQ012QG","path":"packs/sf2e/spells/spells/rank-1/reparative-nanites.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"f33bbcb1ed8569c806477368b179f517ac648567d73e050634e2d3a8a01607e4","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"158","url":"https://2e.aonsrd.com/spells/468-reparative-nanites"}},"content_source_id":900,"version":"1.0"},{"name":"Rewire Flesh","rank":5,"uuid":5893015336468584,"traditions":["divine","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":"Will","cost":"","trigger":null,"requirements":null,"range":"120 feet","area":null,"targets":"1 living creature","duration":"","description":"You rewrite the target's DNA as if it was code, painfully warping its biological functions to mimic the processes of a robot: its body becomes visibly robotic as its blood vessels form circuit-like patterns, its bones twist into straight lines, its movements become jerky, and its voice grows halting. The target takes 3d6 slashing damage and 3d6 persistent bleed damage and must attempt a Will save.\n\n**Critical Success** The target is unaffected.\n\n**Success** The target takes half damage and is clumsy 1 for 1 round.\n\n**Failure** The target takes full damage, is clumsy 2 for 1 minute, and takes a –10-foot penalty to its Speeds for as long as it's clumsy.\n\n**Critical Failure** As failure, but the target takes double damage and is also stupefied 1 for as long as it's clumsy.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The slashing damage and persistent bleed damage each increase by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"0LQLmBrjK5B4mYQP","path":"packs/sf2e/spells/spells/rank-5/rewire-flesh.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"694e6bcf1b3e0ae954d3a1bcc1404cdf257da00389e6c505e5407d85866a91b3","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"158","url":"https://2e.aonsrd.com/spells/469-rewire-flesh"}},"content_source_id":900,"version":"1.0"},{"name":"Robo-Fist","rank":2,"uuid":439473196060809,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"ONE-ACTION","traits":[1432,1433,1456],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"","area":null,"targets":"","duration":"sustained up to 1 minute","description":"With a flash of magic, two of your limbs grow wires and plating before snapping together into a robotic structure, ending in an oversized and empowered robot fist. While you maintain these robot fists, the damage die for your [fist](link_item_9252) increases to 1d6 instead of 1d4. You don't take the normal –2 circumstance penalty when making a lethal attack with your [fist](link_item_9252) or any other unarmed attacks.\n\nUp to twice when you [Sustain](link_action_19858) this spell, you can launch one of your robot fists as a rocket, dealing 2d6 [fire](link_trait_1542) damage to all creatures in a 10-foot burst up to 60 feet away (basic Reflex save). Once you've launched both your robot fists, the spell ends.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The [fire](link_trait_1542) damage increases by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"DwAvbUFR5LID5ebL","path":"packs/sf2e/spells/spells/rank-2/robo-fist.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"0515e87e379728320e9c8ec312a90f089d9ab8cf84f85cb9bc75b7372fcebc50","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"159","url":"https://2e.aonsrd.com/spells/470-robo-fist"}},"content_source_id":900,"version":"1.0"},{"name":"Scrap Shell","rank":1,"uuid":1488496705989497,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"REACTION","traits":[1432,5225,1433],"defense":null,"cost":"","trigger":"You're critically hit by a damage-dealing effect or [Strike](link_action_19856).","requirements":null,"range":"","area":null,"targets":"","duration":"","description":"You snap a layer of brittle scrap into place between you and the triggering blow, the scrap shatters and absorbs some of the force of the impact. The scrap has Hardness 5 and 10 Hit Points. If the scrap is destroyed, you take any excess damage that the scrap didn't absorb. After taking the blow, the scrap collapses into a pile of junk.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The scrap's Hit Points increase by 10."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"rBlHYUZH1anYD4cg","path":"packs/sf2e/spells/spells/rank-1/scrap-shell.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"0dd6139c2d5ac8905d12ecf867dfbfbe8ab50ad1ce2988eca4630a322660ef2d","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"159","url":"https://2e.aonsrd.com/spells/471-scrap-shell"}},"content_source_id":900,"version":"1.0"},{"name":"Scrap Spray","rank":1,"uuid":4791833109936286,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,5225,1433],"defense":"Reflex","cost":"","trigger":null,"requirements":null,"range":"30 feet","area":"15-foot cone","targets":"","duration":"","description":"You spray a blast of jagged scrap in an area in front of you. The _[scrap spray](link_spell_{{allocated:4791833109936286}})_ deals 1d6 bludgeoning, slashing, or piercing damage to each creature in the area. Each creature must attempt a Reflex save.\n\n**Critical Success** The creature is unaffected.\n\n**Success** The creature takes half damage.\n\n**Failure** The creature takes full damage and is suppressed until the beginning of your next turn.\n\n**Critical Failure** The creature takes double damage and is suppressed until the beginning of your next turn.","heightened":{"data":{},"text":[{"amount":"(+2)","text":"Increase the damage by 3d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"dO7QnIrHTwmCzKQB","path":"packs/sf2e/spells/spells/rank-1/scrap-spray.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"6e1433dc69bc05122b0182eb19a9b88f70a3e78456a82c84488e87b9b4ccab46","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"159","url":"https://2e.aonsrd.com/spells/472-scrap-spray"}},"content_source_id":900,"version":"1.0"},{"name":"Shield Wall","rank":6,"uuid":4056384505777897,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":"You're holding a shield, used as a locus.","range":"","area":null,"targets":"","duration":"1 minute","description":"You magnify the protective power of your shield, slamming it into the ground and causing it to grow into a wall up to 60 feet long, 30 feet high, and 1/4 inch thick. The wall is made of the same material as the locus and doesn't need to stand vertically, forming a straight line parallel to the shield's surface. If the wall would pass through a creature or object, the spell is lost. Each 10-foot-by-10-foot section of the wall has AC 10, is immune to critical hits and precision damage, and has the same Hardness, HP, and BT as the locus. Creatures can move through a section of the wall that's broken.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"i4KJpgO0nv6TY73L","path":"packs/sf2e/spells/spells/rank-6/shield-wall.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"a6c143286191440eb284e6fc505ea5be6ea137527c49150fecb25756b2348d61","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"159","url":"https://2e.aonsrd.com/spells/473-shield-wall"}},"content_source_id":900,"version":"1.0"},{"name":"Spark of the Spirit","rank":6,"uuid":7179770405090839,"traditions":["divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1576,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"60 feet","area":"20-foot burst","targets":"","duration":"1 minute","description":"You create a sphere of spiritual [electricity](link_trait_1576). Each ally that begins their turn in the area is quickened and can use this additional action only to [Interact](link_action_19733) or [Step](link_action_19853). Allies quickened in this way immediately regain all charges on batteries in their possession and deal an additional 3d4 [electricity](link_trait_1576) damage when they [Strike](link_action_19856) with a [tech](link_trait_4506) weapon.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"S1nvwfmweG4AEGGW","path":"packs/sf2e/spells/spells/rank-6/spark-of-the-spirit.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"40719a95d47be904e7782b6a6f21261b11cfca5b16f55ecc35c7d83516548909","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"159","url":"https://2e.aonsrd.com/spells/474-spark-of-the-spirit"}},"content_source_id":900,"version":"1.0"},{"name":"Summon Drift Prophet","rank":5,"uuid":3355644190484034,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,2584,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"100 feet","area":null,"targets":"","duration":"until the end of your next turn","description":"You call forth a spectra tasked with monitoring the Drift and presenting its gift to technologically advanced civilizations. The spectra occupies the space of a Large creature, and has a Speed of 40 feet and a fly Speed of 60 feet with the [cosmic](link_trait_4513) trait.\n\n**Arrive** _Establish Universal Network_ With a burst of divine energy from the Drift, the spectra restores 20 Hit Points to all creatures or objects with the [tech](link_trait_4506) trait within a 30-foot emanation and reduces their glitching condition by 5.\n\n**Depart** _Terminate Connection_ Each creature or attended object with the [tech](link_trait_4506) trait within a 30-foot emanation must attempt a Fortitude save. On a failed save, the creature or object becomes glitching 5, and creatures are slowed 1 while they're glitching.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"Increase the Hit Points restored by 5."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"IKzuw8XgMMw7ErSJ","path":"packs/sf2e/spells/spells/rank-5/summon-drift-prophet.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"291cf0a8c7d117186acbb2c069be29fdd60b22a65f463ad28f39d17e497e1647","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"159","url":"https://2e.aonsrd.com/spells/475-summon-drift-prophet"}},"content_source_id":900,"version":"1.0"},{"name":"Summon Giant Robot","rank":9,"uuid":8534034113939344,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,2584,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"100 feet","area":null,"targets":"","duration":"until the end of your next turn","description":"You call forth a titanic robot. The robot occupies the space of a Huge creature, and has a Speed of 80 feet and a fly Speed of 100 feet with the [cosmic](link_trait_4513) trait.\n\n**Arrive** _Ultra Cannon Onslaught_ ([traversal](link_trait_4533)) The robot [Strides](link_action_19855) once in a straight line, trampling enemies underfoot to deal 10d8 bludgeoning damage (basic Reflex save). It then unleashes a volley of lasers from its chest in a 60-foot cone or 120-foot line, which can't overlap with the area of the its [Stride](link_action_19855), dealing 10d8 [force](link_trait_1560) damage (basic Reflex save).\n\n**Depart** _Missile Silo Unleashed_ The robot fires rockets at up to 8 different creatures up to 120 feet away, dealing 9d8 [fire](link_trait_1542) damage (basic Reflex save).","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"UDhfM3MWs5yAsCvx","path":"packs/sf2e/spells/spells/rank-9/summon-giant-robot.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"a485401c2737bc3135b94625de0dc64a78f8c77e865653cd5ac906ad41310336","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"159","url":"https://2e.aonsrd.com/spells/476-summon-giant-robot"}},"content_source_id":900,"version":"1.0"},{"name":"Sure Tracking","rank":2,"uuid":6538713188872701,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"30 feet","area":null,"targets":"1 ranged weapon with the [tech](link_trait_4506) trait","duration":"1 minute","description":"You upgrade a weapon to fire ammunition that can make precise adjustments to its position in space to better track targets. A creature using the weapon reduces the penalty for firing into the weapon's second range increment from –2 to 0. Additionally, whenever a creature makes a ranged [Strike](link_action_19856) with the weapon that targets a single creature, the attack ignores the target's circumstance bonus to AC from cover.","heightened":{"data":{},"text":[{"amount":"(5th)","text":"You can target up to 10 weapons."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"UeodgQQ4yBFDOPEK","path":"packs/sf2e/spells/spells/rank-2/sure-tracking.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"35a2e9710c19a7edd54e7b93e1caea0c44f68427d38d4ae727512c164b4f3abd","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"160","url":"https://2e.aonsrd.com/spells/477-sure-tracking"}},"content_source_id":900,"version":"1.0"},{"name":"Surveillance Vision","rank":4,"uuid":2961664371227917,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"1 minute","traits":[1432,1433,1590],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"10 feet","area":null,"targets":"1 solid surface","duration":"8 hours","description":"You create an invisible security camera with 1 HP and AC 10 anywhere within 10 feet on a solid surface. It sees in all directions with your normal visual senses. You can constantly perceive through your own senses and the vision of the camera as long as you're on the same plane. Only one camera can be active at a time; if you make a second camera, the first is destroyed. You can [Dismiss](link_action_19627) this spell.","heightened":{"data":{},"text":[{"amount":"(7th)","text":"The duration becomes unlimited."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"cn0QFZOBORN9mwr0","path":"packs/sf2e/spells/spells/rank-4/surveillance-vision.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"c070e6fe2822a35ccdb60ca51763ea5ef0a292161de20b880bea179c6c8a5f1c","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"160","url":"https://2e.aonsrd.com/spells/478-surveillance-vision"}},"content_source_id":900,"version":"1.0"},{"name":"Technological Combustion","rank":5,"uuid":5442129916430851,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1542,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"60 feet","area":null,"targets":"1 object or weapon with the [tech](link_trait_4506) trait","duration":"","description":"You rapidly overheat the systems of a technological weapon, causing it to expel a devastating wave of heat. If the target is held or worn, the creature holding or wielding it attempts a Reflex save. On a failure, or if the target is unattended, the target becomes glitching 2, and all creatures within 20 feet of the target take 5d10 [fire](link_trait_1542) damage with a basic Reflex save.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 1d10."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"e65BnxbVVAMZ3Kqt","path":"packs/sf2e/spells/spells/rank-5/technological-combustion.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"d64c3c986b382b7ea8839e0938536f38059bc92cb589a288967b28716d3b72bb","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"160","url":"https://2e.aonsrd.com/spells/479-technological-combustion"}},"content_source_id":900,"version":"1.0"},{"name":"Technophobia","rank":5,"uuid":4310446980159488,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1486,1487,1433,1448],"defense":"Will","cost":"","trigger":null,"requirements":"A [comm unit](link_item_18663) connected to an infosphere, used as a locus.","range":"60 feet","area":null,"targets":"1 creature","duration":"","description":"You gather the message threads of thousands of angry technology users from the infosphere, making their pain a reality for your target whenever they use technology. The target must attempt a Will saving throw.\n\n**Critical Success** The target is unaffected.\n\n**Success** The first time each round the target uses a [tech](link_trait_4506) item, it takes 2d10 [mental](link_trait_1448) damage.\n\n**Failure** As success, but the target becomes frightened 1 and takes 4d10 [mental](link_trait_1448) damage.\n\n**Critical Failure** As success, but the target becomes frightened 2 and takes 8d10 [mental](link_trait_1448) damage.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"fs6YggxBweDzV3yG","path":"packs/sf2e/spells/spells/rank-5/technophobia.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"058d1ce335e528715359e7312ae2fe1f5bc12c1535fd60e137adfa77c2e9dc8d","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"160","url":"https://2e.aonsrd.com/spells/480-technophobia"}},"content_source_id":900,"version":"1.0"},{"name":"Transfer Consciousness","rank":8,"uuid":168884402527252,"traditions":["occult","primal"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1433,2133],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"touch","area":null,"targets":"1 willing computer or [tech](link_trait_4506) [construct](link_trait_2410)","duration":"varies","description":"You project your mind into an advanced piece of technology, allowing you to interact with its systems as if they were your own body. The target's level must be equal to or lower than your own. Your own body is helpless and falls prone as if you were unconscious. At the end of the spell, your mind returns to your body instantly as long as your body and the target are on the same plane. Otherwise, the spell becomes permanent, and your real body enters a coma.\n\nWhile your mind is in a computer, for 1 hour, you can roll your spell attack modifier instead of Computers for Computers skill actions related to that system, and you can attempt trained Computers skill actions even if you're untrained.\n\nWhile your mind is in a construct, you have access to its physical functions, allowing you to control it as if it was your own body for 1 minute. You can use any special actions the construct has access to, though you can't cast its spells, if any. You can cast your own spells using the construct's body.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"iPfHkWGAwocCqU1E","path":"packs/sf2e/spells/spells/rank-8/transfer-consciousness.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"2f61e9e0f5feee920f90084ab41356db1f2d66f6f4127daf5499121a8d127101","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"160","url":"https://2e.aonsrd.com/spells/481-transfer-consciousness"}},"content_source_id":900,"version":"1.0"},{"name":"Turbulent Toys","rank":3,"uuid":5757831548251458,"traditions":["arcane","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433],"defense":"varies","cost":"","trigger":null,"requirements":null,"range":"30 feet","area":"10-foot burst","targets":"","duration":"sustained up to 1 minute","description":"Magical battery-powered children's toys fill the area and begin rolling, bumping, and flipping over one another. The toys are semi-corporeal constructs that can't be moved or damaged. When you [Cast the Spell](link_action_19611) and the first time you [Sustain](link_action_19858) it each subsequent round, you choose the turbulence the toys create, then move the area up to 5 feet.\n\n- **Ankle Bumpers** The toys jostle against the feet of creatures in the area, and each creature must succeed at a Reflex save or fall prone.\n- **Battery Hogs** The toys steal energy to power themselves. All battery-operated devices in the area lose 2 charges.\n- **Strobe Rave** The toys unleash a dizzying array of flashing lights and puffs of colored smoke. Each creature in the area must succeed at a Will save or be dazzled until the start of your next turn. This effect has the [visual](link_trait_1479) trait.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"jAPEfvqa62jUPuL6","path":"packs/sf2e/spells/spells/rank-3/turbulent-toys.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"6debce99a059ea22ae8e8141fd4c76e7f2fd574129468e15dff1b7e292a5dca2","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"160","url":"https://2e.aonsrd.com/spells/482-turbulent-toys"}},"content_source_id":900,"version":"1.0"},{"name":"Upgrade Construct","rank":3,"uuid":1442284643120741,"traditions":["arcane","divine"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1433,1456],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"touch","area":null,"targets":"1 creature with the [tech](link_trait_4506) trait","duration":"10 minutes","description":"You upgrade the weapons and armor of the target. The target gains a +1 status bonus to AC, and the target's [Strikes](link_action_19856) deal an additional 2d4 damage of the same type as the base weapon.","heightened":{"data":{},"text":[{"amount":"(+3)","text":"The status bonus to AC increases by 1, and the additional damage increases by 1d4."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"nMOmER5WBdCEkn6v","path":"packs/sf2e/spells/spells/rank-3/upgrade-construct.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"98ed2afb2d296627d2139b826538be134d0570edccb8b92d54064d98c5adc5c8","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"161","url":"https://2e.aonsrd.com/spells/483-upgrade-construct"}},"content_source_id":900,"version":"1.0"},{"name":"Wall of Coiling Lightning","rank":6,"uuid":1488551371766406,"traditions":["arcane"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,1576,1433],"defense":"basic Reflex","cost":"","trigger":null,"requirements":null,"range":"120 feet","area":null,"targets":"","duration":"1 minute","description":"You create 20-foot-tall metal coils that harness the power of [electricity](link_trait_1576), arcing current between two unoccupied spaces up to 30 feet apart. These coils each have AC 10, 60 Hit Points, and are immune to critical hits and precision damage. The spell ends if either coil is destroyed. A constant stream of [electricity](link_trait_1576) flows between these coils in a visible, straight line. Creatures can see and move through the coils; however, if a creature enters or starts its turn in the stream of [electricity](link_trait_1576) or within 5 feet of a coil, it takes 4d12 [electricity](link_trait_1576) damage with a basic Reflex save. On a failed save, the target is also off-guard for 1 round.","heightened":{"data":{},"text":[{"amount":"(+2)","text":"The damage increases by 1d12."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"vgagfjqR9N572poC","path":"packs/sf2e/spells/spells/rank-6/wall-of-coiling-lightning.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"6d460421ccf1da392901862d7db57b2634a29031b6520b54bf898e0490ee1aa7","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"161","url":"https://2e.aonsrd.com/spells/484-wall-of-coiling-lightning"}},"content_source_id":900,"version":"1.0"},{"name":"Wall of Junk","rank":5,"uuid":3720422239519208,"traditions":["arcane","occult"],"rarity":"COMMON","availability":null,"cast":"THREE-ACTIONS","traits":[1432,5225,1433],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"120 feet","area":null,"targets":"","duration":"1 minute","description":"You sculpt a barrier of trash that blocks sight and once broken, impedes foes. You create a 1-foot-thick wall of junk in either a hemisphere with a radius of 10 feet or a straight line up to 60 feet long and 10 feet high. The wall doesn't have to be vertical, but it must be anchored on both sides to a solid surface and can't pass through any creatures or objects, or the spell is lost.\n\nEach 10-foot-by-10-foot section of the wall has AC 10, Hardness 5, 20 Hit Points, and is immune to critical hits and precision damage. A destroyed section leaves behind a heap of jagged scrap that's difficult and hazardous terrain, dealing 2d6 slashing damage to a creature that enters the terrain for the first time on its turn.","heightened":{"data":{},"text":[{"amount":"(+2)","text":"The slashing damage increases by 1d6."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"bTTakzdSo2S8fX92","path":"packs/sf2e/spells/spells/rank-5/wall-of-junk.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"dead30a41058ca058af2206ebf8c9b7a62ee4fd59efc0662027bc1b6776c669a","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"161","url":"https://2e.aonsrd.com/spells/485-wall-of-junk"}},"content_source_id":900,"version":"1.0"},{"name":"Wishborne Shot","rank":1,"uuid":4220991546586871,"traditions":["divine","occult"],"rarity":"COMMON","availability":null,"cast":"ONE-ACTION","traits":[1432,1433],"defense":null,"cost":"","trigger":null,"requirements":"You're wielding a ranged weapon, used as a locus.","range":"","area":null,"targets":"","duration":"","description":"You wish for your next shot to go where you desire. The next time you make a [Strike](link_action_19856) with the locus before the end of your turn, you ignore your target's cover and any flat check required due to the target being concealed or hidden.","heightened":{"data":{},"text":[]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false,"id":"NjsSsNlo2H0Duj7A","path":"packs/sf2e/spells/spells/rank-1/wishborne-shot.json","revision":"581c2bf2ca9734f4dd83f034fbcc93f8e4fd96eb","sha256":"929762c16e81be468492b3ac93d9c8175783015d91650c2cf7b50cd66f7a17b0","publication":{"license":"ORC","remaster":true,"title":"Starfinder Tech Core"}},"source":{"book":"Tech Core","page":"161","url":"https://2e.aonsrd.com/spells/486-wishborne-shot"}},"content_source_id":900,"version":"1.0"},{"name":"Cosmic Bombardment","rank":1,"uuid":2106029419963163,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"ONE-TO-THREE-ACTIONS","traits":[1432,1433,5236],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"sensor range","area":null,"targets":"1 starship","duration":"","description":"You fire a missile made of concentrated magical energy that automatically hits the target starship and deals 1d4+1 [force](link_trait_1560) damage. For each additional action you use when [Casting the Spell](link_action_19611), increase the number of missiles you shoot by one, to a maximum of three missiles for 3 actions. You choose the target for each missile individually. If you shoot more than one missile at the same target, combine the damage before applying bonuses or penalties to damage, resistances, weaknesses, and so forth.","heightened":{"data":{},"text":[{"amount":"(+2)","text":"You fire one additional missile with each action you spend."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"181","url":"https://2e.aonsrd.com/spells/503-cosmic-bombardment"}},"content_source_id":900,"version":"1.0"},{"name":"Cosmic Cannon","rank":0,"uuid":5090364727876872,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1520,1858,1432,1433,5236],"defense":"AC","cost":"","trigger":null,"requirements":null,"range":"sensor range","area":null,"targets":"1 starship","duration":"","description":"Make a ranged spell attack roll against the target's AC. If you hit, you deal 2d4 [force](link_trait_1560) damage (double on a critical success).","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The damage increases by 1d4."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"181","url":"https://2e.aonsrd.com/spells/504-cosmic-cannon"}},"content_source_id":900,"version":"1.0"},{"name":"Cosmic Fortification","rank":1,"uuid":7183600353718648,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"ONE-ACTION","traits":[1432,1433,5236],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"sensor range","area":null,"targets":"1 starship","duration":"","description":"You grant 1d4+4 Shield Points to the target.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The SP restored increases by 1d4+4."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"181","url":"https://2e.aonsrd.com/spells/505-cosmic-fortification"}},"content_source_id":900,"version":"1.0"},{"name":"Cosmic Repairs","rank":1,"uuid":2808844134499571,"traditions":["arcane","divine","occult","primal"],"rarity":"COMMON","availability":null,"cast":"TWO-ACTIONS","traits":[1432,1442,1433,5236],"defense":null,"cost":"","trigger":null,"requirements":null,"range":"sensor range","area":null,"targets":"1 starship","duration":"","description":"You restore 1d8+8 Hull Points to the target.","heightened":{"data":{},"text":[{"amount":"(+1)","text":"The HP restored increases by 1d8+8."}]},"meta_data":{"damage":[],"foundry":{"rules":[],"is_focus":false},"source":{"book":"Tech Core","page":"181","url":"https://2e.aonsrd.com/spells/506-cosmic-repairs"}},"content_source_id":900,"version":"1.0"}],"bindings":[{"owner_uuid":299866193306417,"target_uuid":299866193306417,"path":["description"],"href":"link_spell_900000507","occurrences":1},{"owner_uuid":2083440659933283,"target_uuid":2083440659933283,"path":["description"],"href":"link_spell_{{allocated:2083440659933283}}","occurrences":1},{"owner_uuid":352877985552298,"target_uuid":352877985552298,"path":["description"],"href":"link_spell_{{allocated:352877985552298}}","occurrences":1},{"owner_uuid":694535347719834,"target_uuid":694535347719834,"path":["description"],"href":"link_spell_{{allocated:694535347719834}}","occurrences":1},{"owner_uuid":3373659099376032,"target_uuid":3373659099376032,"path":["description"],"href":"link_spell_{{allocated:3373659099376032}}","occurrences":2},{"owner_uuid":2057495414296206,"target_uuid":2057495414296206,"path":["description"],"href":"link_spell_{{allocated:2057495414296206}}","occurrences":1},{"owner_uuid":910297482701427,"target_uuid":910297482701427,"path":["heightened","text","0","text"],"href":"link_spell_{{allocated:910297482701427}}","occurrences":1},{"owner_uuid":4791833109936286,"target_uuid":4791833109936286,"path":["description"],"href":"link_spell_{{allocated:4791833109936286}}","occurrences":1}]}$tech_core_general$::jsonb;
