  allocated_id bigint;
  ids jsonb := '{}'::jsonb;
begin
  lock table public.content_update in share mode;
  lock table public.spell in share row exclusive mode;
  perform s.id from public.content_source s where s.id in(select (p->>'id')::bigint from jsonb_array_elements(v_spec->'sources') p) order by s.id for update;
  perform r.id from public.trait r where r.id in(select (p#>>'{row,id}')::bigint from jsonb_array_elements(v_spec->'references') p where p->>'table'='trait') order by r.id for share;
  perform r.id from public.ability_block r where r.id in(select (p#>>'{row,id}')::bigint from jsonb_array_elements(v_spec->'references') p where p->>'table'='ability_block') order by r.id for share;
  perform r.id from public.item r where r.id in(select (p#>>'{row,id}')::bigint from jsonb_array_elements(v_spec->'references') p where p->>'table'='item') order by r.id for share;
  with recursive settings as materialized(select v_spec as spec),
raw_expected as materialized(select false as prior,p as row from settings cross join lateral jsonb_array_elements(spec->'rows') p
  union all select true,p from settings cross join lateral jsonb_array_elements(spec->'prior_rows') p),
ordered_bindings as materialized(select b,row_number() over(partition by b->>'owner_uuid' order by n)::integer as step
  from settings cross join lateral jsonb_array_elements(spec->'bindings') with ordinality as t(b,n)),
identity_map as materialized(select e.row->>'uuid' as uuid,r.id from raw_expected e join public.spell r on r.uuid=(e.row->>'uuid')::bigint),
resolved(prior,row,step) as(
  select prior,row,0 from raw_expected
  union all select r.prior,jsonb_set(r.row,array(select jsonb_array_elements_text(b.b->'path')),
    to_jsonb(replace(r.row#>>array(select jsonb_array_elements_text(b.b->'path')),'('||(b.b->>'href')||')','(link_spell_'||i.id::text||')')),false),r.step+1
  from resolved r join ordered_bindings b on b.b->>'owner_uuid'=r.row->>'uuid' and b.step=r.step+1
  join identity_map i on i.uuid=b.b->>'target_uuid' and i.id>0),
expected as materialized(select r.prior,r.row from resolved r where not exists(select 1 from ordered_bindings b where b.b->>'owner_uuid'=r.row->>'uuid' and b.step=r.step+1)),
actual as materialized(select e.prior,e.row,r.id,to_jsonb(r)-'id'-'created_at'-'updated_at'-'search_tsv' as actual_row from expected e join public.spell r on r.uuid=(e.row->>'uuid')::bigint),
aliases as materialized(select e.prior,r.id from raw_expected e join public.spell r on r.uuid=(e.row->>'uuid')::bigint
  or (r.content_source_id=900 and lower(btrim(r.name))=lower(btrim(e.row->>'name')))
  or lower(btrim(r.meta_data#>>'{source,url}'))=lower(btrim(e.row#>>'{meta_data,source,url}'))),
reference_rows as materialized(select 'trait'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.trait r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='trait')
  union all select 'ability_block'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.ability_block r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='ability_block')
  union all select 'item'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.item r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='item')
  union all select 'spell'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.spell r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='spell')),
dependencies as materialized(select coalesce(count(*)=92 and bool_and(r.row is not null and r.row=p->'row'),false) as passed
  from settings cross join lateral jsonb_array_elements(spec->'references') p left join reference_rows r on r.table_name=p->>'table' and r.row->>'id'=p#>>'{row,id}'),
sources as materialized(select coalesce(count(*)=7 and bool_and(s.id is not null and jsonb_build_object('id',s.id,'name',s.name,'user_id',s.user_id,'is_published',s.is_published,'deprecated',s.deprecated,'url',s.url,'group',s."group",'required_content_sources',s.required_content_sources,'require_key',s.require_key)=p),false) as passed
  from settings cross join lateral jsonb_array_elements(spec->'sources') p left join public.content_source s on s.id=(p->>'id')::bigint),
binding_literals as materialized(select coalesce(count(*)=8 and count(distinct b)=8 and bool_and(coalesce(e.row is not null
  and jsonb_typeof(e.row#>array(select jsonb_array_elements_text(b->'path')))='string'
  and (b->>'occurrences')::integer>0
  and (length(e.row#>>array(select jsonb_array_elements_text(b->'path')))-length(replace(e.row#>>array(select jsonb_array_elements_text(b->'path')),'('||(b->>'href')||')','')))/length('('||(b->>'href')||')')=(b->>'occurrences')::integer,false)),false) as passed
  from settings cross join lateral jsonb_array_elements(spec->'bindings') b left join raw_expected e on e.row->>'uuid'=b->>'owner_uuid'),
pending as materialized(select exists(select 1 from public.content_update u cross join settings where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in('APPROVED','REJECTED') and (
  (u.type='spell' and exists(select 1 from raw_expected e where u.data->>'uuid'=e.row->>'uuid'
    or u.ref_id in(select id from identity_map where uuid=e.row->>'uuid')
    or u.data->>'id' in(select id::text from identity_map where uuid=e.row->>'uuid')
    or ((u.content_source_id=900 or u.data->>'content_source_id'='900') and lower(btrim(u.data->>'name'))=lower(btrim(e.row->>'name')))
    or lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(e.row#>>'{meta_data,source,url}'))))
  or exists(select 1 from jsonb_array_elements(spec->'references') p where u.type in(p->>'table',replace(p->>'table','_','-'),p#>>'{row,type}') and (
    u.ref_id=(p#>>'{row,id}')::bigint or u.data->>'id'=p#>>'{row,id}' or u.data->>'uuid'=p#>>'{row,uuid}'
    or ((u.content_source_id=(p#>>'{row,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{row,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{row,name}')))
    or (coalesce(btrim(p#>>'{row,meta_data,source,url}'),'')<>'' and lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(p#>>'{row,meta_data,source,url}')))))
  or (u.type in('content-source','content_source') and exists(select 1 from jsonb_array_elements(spec->'sources') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(p->>'name'))))
)) as present),
state as(select (select passed from dependencies) and (select passed from sources) and (select passed from binding_literals) and not(select present from pending)
    and (select count(distinct id) from aliases where prior)=6
    and (select count(*) from actual where prior and id>0 and actual_row=row and position('{{allocated:' in row::text)=0)=6 as prerequisites,
  (select count(distinct id) from aliases where not prior) as aliases,
  (select count(*) from actual where not prior and id>0 and actual_row=row and position('{{allocated:' in row::text)=0)=76 as exact_rows)
select prerequisites,aliases,exact_rows into status from state;
  if not status.prerequisites then raise exception 'Tech Core general spell prerequisites differ or have a pending curator submission'; end if;
  if status.aliases=76 and status.exact_rows then return; end if;
  if status.aliases<>0 then raise exception 'Tech Core general spells are partially present or differ from the reviewed insert'; end if;
  for proposed in select p from jsonb_array_elements(v_spec->'rows') p order by p->>'name' loop
    allocated_id := nextval(pg_get_serial_sequence('public.spell','id'));
    if allocated_id<=0 or exists(select 1 from public.spell where id=allocated_id) then raise exception 'Tech Core general spell identity must be positive and unused'; end if;
    if allocated_id in(select value::bigint from jsonb_each_text(ids)) then raise exception 'Tech Core general spell identity allocation must be distinct'; end if;
    ids := ids||jsonb_build_object(proposed->>'uuid',allocated_id);
  end loop;
  for proposed in select p from jsonb_array_elements(v_spec->'rows') p order by p->>'name' loop
    allocated_id := (ids->>(proposed->>'uuid'))::bigint;
    for binding in select p from jsonb_array_elements(v_spec->'bindings') with ordinality as b(p,n) where p->>'owner_uuid'=proposed->>'uuid' order by n loop
      path := array(select jsonb_array_elements_text(binding->'path'));
      text_value := proposed#>>path;
      if text_value is null or jsonb_typeof(proposed#>path)<>'string' or (binding->>'occurrences')::integer<=0
        or (length(text_value)-length(replace(text_value,'('||(binding->>'href')||')','')))/length('('||(binding->>'href')||')')<>(binding->>'occurrences')::integer
        or not(ids ? (binding->>'target_uuid')) then raise exception 'Tech Core general spell whole-reference occurrence or target differs'; end if;
      proposed := jsonb_set(proposed,path,to_jsonb(replace(text_value,'('||(binding->>'href')||')','(link_spell_'||(ids->>(binding->>'target_uuid'))||')')),false);
    end loop;
    if position('{{allocated:' in proposed::text)>0 or position('@@WGTCREF' in proposed::text)>0 then raise exception 'Tech Core general spell contains an unresolved reference'; end if;
    insert into public.spell("id","name","rank","uuid","traditions","rarity","availability","cast","traits","defense","cost","trigger","requirements","range","area","targets","duration","description","heightened","meta_data","content_source_id","version") select allocated_id,r."name",r."rank",r."uuid",r."traditions",r."rarity",r."availability",r."cast",r."traits",r."defense",r."cost",r."trigger",r."requirements",r."range",r."area",r."targets",r."duration",r."description",r."heightened",r."meta_data",r."content_source_id",r."version" from jsonb_populate_record(null::public.spell,proposed) r;
  end loop;
  with recursive settings as materialized(select v_spec as spec),
raw_expected as materialized(select false as prior,p as row from settings cross join lateral jsonb_array_elements(spec->'rows') p
  union all select true,p from settings cross join lateral jsonb_array_elements(spec->'prior_rows') p),
ordered_bindings as materialized(select b,row_number() over(partition by b->>'owner_uuid' order by n)::integer as step
  from settings cross join lateral jsonb_array_elements(spec->'bindings') with ordinality as t(b,n)),
identity_map as materialized(select e.row->>'uuid' as uuid,r.id from raw_expected e join public.spell r on r.uuid=(e.row->>'uuid')::bigint),
resolved(prior,row,step) as(
  select prior,row,0 from raw_expected
  union all select r.prior,jsonb_set(r.row,array(select jsonb_array_elements_text(b.b->'path')),
    to_jsonb(replace(r.row#>>array(select jsonb_array_elements_text(b.b->'path')),'('||(b.b->>'href')||')','(link_spell_'||i.id::text||')')),false),r.step+1
  from resolved r join ordered_bindings b on b.b->>'owner_uuid'=r.row->>'uuid' and b.step=r.step+1
  join identity_map i on i.uuid=b.b->>'target_uuid' and i.id>0),
expected as materialized(select r.prior,r.row from resolved r where not exists(select 1 from ordered_bindings b where b.b->>'owner_uuid'=r.row->>'uuid' and b.step=r.step+1)),
actual as materialized(select e.prior,e.row,r.id,to_jsonb(r)-'id'-'created_at'-'updated_at'-'search_tsv' as actual_row from expected e join public.spell r on r.uuid=(e.row->>'uuid')::bigint),
aliases as materialized(select e.prior,r.id from raw_expected e join public.spell r on r.uuid=(e.row->>'uuid')::bigint
  or (r.content_source_id=900 and lower(btrim(r.name))=lower(btrim(e.row->>'name')))
  or lower(btrim(r.meta_data#>>'{source,url}'))=lower(btrim(e.row#>>'{meta_data,source,url}'))),
reference_rows as materialized(select 'trait'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.trait r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='trait')
  union all select 'ability_block'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.ability_block r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='ability_block')
  union all select 'item'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.item r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='item')
  union all select 'spell'::text as table_name,to_jsonb(r)-'updated_at'-'search_tsv' as row from public.spell r
  where r.id in(select (p#>>'{row,id}')::bigint from settings cross join lateral jsonb_array_elements(spec->'references') p where p->>'table'='spell')),
dependencies as materialized(select coalesce(count(*)=92 and bool_and(r.row is not null and r.row=p->'row'),false) as passed
  from settings cross join lateral jsonb_array_elements(spec->'references') p left join reference_rows r on r.table_name=p->>'table' and r.row->>'id'=p#>>'{row,id}'),
sources as materialized(select coalesce(count(*)=7 and bool_and(s.id is not null and jsonb_build_object('id',s.id,'name',s.name,'user_id',s.user_id,'is_published',s.is_published,'deprecated',s.deprecated,'url',s.url,'group',s."group",'required_content_sources',s.required_content_sources,'require_key',s.require_key)=p),false) as passed
  from settings cross join lateral jsonb_array_elements(spec->'sources') p left join public.content_source s on s.id=(p->>'id')::bigint),
binding_literals as materialized(select coalesce(count(*)=8 and count(distinct b)=8 and bool_and(coalesce(e.row is not null
  and jsonb_typeof(e.row#>array(select jsonb_array_elements_text(b->'path')))='string'
  and (b->>'occurrences')::integer>0
  and (length(e.row#>>array(select jsonb_array_elements_text(b->'path')))-length(replace(e.row#>>array(select jsonb_array_elements_text(b->'path')),'('||(b->>'href')||')','')))/length('('||(b->>'href')||')')=(b->>'occurrences')::integer,false)),false) as passed
  from settings cross join lateral jsonb_array_elements(spec->'bindings') b left join raw_expected e on e.row->>'uuid'=b->>'owner_uuid'),
pending as materialized(select exists(select 1 from public.content_update u cross join settings where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in('APPROVED','REJECTED') and (
  (u.type='spell' and exists(select 1 from raw_expected e where u.data->>'uuid'=e.row->>'uuid'
    or u.ref_id in(select id from identity_map where uuid=e.row->>'uuid')
    or u.data->>'id' in(select id::text from identity_map where uuid=e.row->>'uuid')
    or ((u.content_source_id=900 or u.data->>'content_source_id'='900') and lower(btrim(u.data->>'name'))=lower(btrim(e.row->>'name')))
    or lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(e.row#>>'{meta_data,source,url}'))))
  or exists(select 1 from jsonb_array_elements(spec->'references') p where u.type in(p->>'table',replace(p->>'table','_','-'),p#>>'{row,type}') and (
    u.ref_id=(p#>>'{row,id}')::bigint or u.data->>'id'=p#>>'{row,id}' or u.data->>'uuid'=p#>>'{row,uuid}'
    or ((u.content_source_id=(p#>>'{row,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{row,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{row,name}')))
    or (coalesce(btrim(p#>>'{row,meta_data,source,url}'),'')<>'' and lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(p#>>'{row,meta_data,source,url}')))))
  or (u.type in('content-source','content_source') and exists(select 1 from jsonb_array_elements(spec->'sources') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(p->>'name'))))
)) as present),
state as(select (select passed from dependencies) and (select passed from sources) and (select passed from binding_literals) and not(select present from pending)
    and (select count(distinct id) from aliases where prior)=6
    and (select count(*) from actual where prior and id>0 and actual_row=row and position('{{allocated:' in row::text)=0)=6 as prerequisites,
  (select count(distinct id) from aliases where not prior) as aliases,
  (select count(*) from actual where not prior and id>0 and actual_row=row and position('{{allocated:' in row::text)=0)=76 as exact_rows)
select prerequisites and aliases=76 and exact_rows as passed into status from state;
  if not status.passed then raise exception 'Tech Core general spell readback differs from the complete reviewed insert'; end if;
end $import_tech_general$;
